import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { API_BASE_URL } from '@/config/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { Loader2, RefreshCw, Smartphone, Megaphone, QrCode, Users, CheckSquare, Search, Paperclip, X, FileText, Image as ImageIcon } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { toast } from '../../hooks/use-toast';
import MessageEditor from '../../components/MessageEditor';
import MessageTemplateSelector from '../../components/MessageTemplateSelector';

const WhatsAppIntegrationPage = () => {
  const { token, user } = useAuth();
  const isVendor = user?.role === 'vendor';
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [broadcasting, setBroadcasting] = useState(false);
  const [testPhone, setTestPhone] = useState('');
  const [testMessage, setTestMessage] = useState('Halo warga, ini pesan percobaan.');
  const [broadcastNumbers, setBroadcastNumbers] = useState('');
  const [broadcastMessage, setBroadcastMessage] = useState('Halo warga, ini pemberitahuan resmi dari pengurus.');
  const [recipientFilter, setRecipientFilter] = useState('manual');
  const [loadingRecipients, setLoadingRecipients] = useState(false);
  const [availableRecipients, setAvailableRecipients] = useState([]);
  const [selectedRecipients, setSelectedRecipients] = useState([]);
  const [showRecipientList, setShowRecipientList] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [attachmentFile, setAttachmentFile] = useState(null);
  const [attachmentPreview, setAttachmentPreview] = useState(null);
  const [uploadingFile, setUploadingFile] = useState(false);

  const fetchStatus = useCallback(async () => {
    if (!token) return;
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp/status`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        throw new Error('Gagal mengambil status WhatsApp');
      }
      const data = await res.json();
      setStatus(data);
    } catch (err) {
      toast({ title: 'Gagal memuat status', description: err.message, variant: 'destructive' });
      setStatus(null);
    } finally {
      setLoading(false);
    }
  }, [token]);

  useEffect(() => {
    fetchStatus();
    const timer = setInterval(fetchStatus, 8000);
    return () => clearInterval(timer);
  }, [fetchStatus]);

  const handleSendTest = async () => {
    if (!testPhone || !testMessage) {
      toast({ title: 'Lengkapi data', description: 'Nomor dan pesan harus diisi', variant: 'destructive' });
      return;
    }
    setSending(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp/send`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ phone: testPhone, message: testMessage }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal mengirim pesan');
      toast({ title: 'Pesan terkirim', description: `Pesan dikirim ke ${testPhone}` });
      setTestPhone('');
    } catch (err) {
      toast({ title: 'Gagal mengirim', description: err.message, variant: 'destructive' });
    } finally {
      setSending(false);
    }
  };

  const handleLoadRecipients = async (filterType) => {
    if (filterType === 'manual') {
      setBroadcastNumbers('');
      setAvailableRecipients([]);
      setSelectedRecipients([]);
      setShowRecipientList(false);
      setSearchQuery('');
      return;
    }

    setLoadingRecipients(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/whatsapp/recipients?filter_type=${filterType}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal memuat daftar warga');
      
      if (data.recipients && data.recipients.length > 0) {
        setAvailableRecipients(data.recipients);
        setShowRecipientList(true);
        setSearchQuery('');
        toast({ 
          title: 'Data berhasil dimuat', 
          description: `${data.total} warga tersedia untuk dipilih`
        });
      } else {
        toast({ 
          title: 'Tidak ada data', 
          description: 'Tidak ada warga yang sesuai dengan filter',
          variant: 'destructive'
        });
        setAvailableRecipients([]);
        setShowRecipientList(false);
      }
    } catch (err) {
      toast({ 
        title: 'Gagal memuat', 
        description: err.message, 
        variant: 'destructive' 
      });
    } finally {
      setLoadingRecipients(false);
    }
  };

  const filteredRecipients = useMemo(() => {
    if (!searchQuery) return availableRecipients;
    
    const query = searchQuery.toLowerCase();
    return availableRecipients.filter(r => 
      r.nama_lengkap.toLowerCase().includes(query) ||
      r.whatsapp.includes(query) ||
      (r.blok_rumah && r.blok_rumah.toLowerCase().includes(query))
    );
  }, [availableRecipients, searchQuery]);

  const handleFileUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validasi tipe file
    const allowedTypes = [
      'application/pdf',
      'image/gif',
      'image/jpeg',
      'image/jpg', 
      'image/png',
      'image/bmp',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    ];

    if (!allowedTypes.includes(file.type)) {
      toast({
        title: 'Tipe file tidak didukung',
        description: 'Hanya mendukung PDF, gambar (GIF, JPEG, JPG, PNG, BMP), DOC, DOCX, XLS, XLSX',
        variant: 'destructive'
      });
      return;
    }

    // Validasi ukuran file (max 10MB)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      toast({
        title: 'File terlalu besar',
        description: 'Ukuran file maksimal 10MB',
        variant: 'destructive'
      });
      return;
    }

    setUploadingFile(true);
    try {
      // Convert file to base64
      const reader = new FileReader();
      reader.onload = () => {
        const base64String = reader.result.split(',')[1]; // Remove data:type;base64, prefix
        setAttachmentFile({
          data: base64String,
          filename: file.name,
          mimetype: file.type
        });

        // Create preview for images
        if (file.type.startsWith('image/')) {
          setAttachmentPreview({
            type: 'image',
            url: reader.result,
            name: file.name
          });
        } else {
          setAttachmentPreview({
            type: 'document',
            name: file.name,
            size: (file.size / 1024).toFixed(2) + ' KB'
          });
        }

        toast({
          title: 'File berhasil diunggah',
          description: `${file.name} siap untuk dikirim`
        });
      };

      reader.onerror = () => {
        toast({
          title: 'Gagal membaca file',
          description: 'Terjadi kesalahan saat membaca file',
          variant: 'destructive'
        });
      };

      reader.readAsDataURL(file);
    } catch (error) {
      toast({
        title: 'Gagal mengunggah file',
        description: error.message,
        variant: 'destructive'
      });
    } finally {
      setUploadingFile(false);
    }
  };

  const handleRemoveAttachment = () => {
    setAttachmentFile(null);
    setAttachmentPreview(null);
    // Reset file input
    const fileInput = document.getElementById('attachment-file-input');
    if (fileInput) fileInput.value = '';
  };

  const replaceTemplateVariables = (message, recipient) => {
    let result = message;
    
    // Replace basic warga info
    result = result.replace(/{nama_warga}/g, recipient.nama_lengkap);
    result = result.replace(/{whatsapp}/g, recipient.whatsapp);
    result = result.replace(/{blok_rumah}/g, recipient.blok_rumah || '-');
    
    // Replace IPL bill info if available
    if (recipient.ipl_bills && recipient.ipl_bills.length > 0) {
      const bill = recipient.ipl_bills[0]; // Use first unpaid bill
      const monthNames = ['', 'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 
                          'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
      
      result = result.replace(/{bulan}/g, monthNames[bill.bulan] || bill.bulan);
      result = result.replace(/{periode}/g, bill.periode || `${bill.bulan}/${bill.tahun}`);
      result = result.replace(/{nominal}/g, new Intl.NumberFormat('id-ID').format(bill.jumlah));
      
      // Calculate due date (end of month)
      const dueDate = new Date(bill.tahun, bill.bulan, 0);
      result = result.replace(/{tanggal_jatuh_tempo}/g, dueDate.toLocaleDateString('id-ID', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      }));
      
      // Handle multiple bills (tunggakan)
      if (recipient.ipl_bills.length > 1) {
        // Generate detailed bill list
        const detailTagihan = recipient.ipl_bills.map(b => {
          const monthName = monthNames[b.bulan] || b.bulan;
          const formatted = new Intl.NumberFormat('id-ID').format(b.jumlah);
          return `📋 ${monthName} ${b.tahun}: Rp ${formatted}`;
        }).join('\n');
        
        // Calculate total tunggakan
        const totalTunggakan = recipient.ipl_bills.reduce((sum, b) => sum + b.jumlah, 0);
        const formattedTotal = new Intl.NumberFormat('id-ID').format(totalTunggakan);
        
        result = result.replace(/{detail_tagihan}/g, detailTagihan);
        result = result.replace(/{total_tunggakan}/g, formattedTotal);
      }
    }
    
    return result;
  };

  const handleRecipientFilterChange = (value) => {
    setRecipientFilter(value);
    handleLoadRecipients(value);
  };

  const handleSelectRecipient = (recipient) => {
    const isSelected = selectedRecipients.some(r => r.id === recipient.id);
    if (isSelected) {
      setSelectedRecipients(selectedRecipients.filter(r => r.id !== recipient.id));
    } else {
      setSelectedRecipients([...selectedRecipients, recipient]);
    }
  };

  const handleSelectAll = () => {
    if (selectedRecipients.length === availableRecipients.length) {
      setSelectedRecipients([]);
    } else {
      setSelectedRecipients([...availableRecipients]);
    }
  };

  const handleAddToList = () => {
    if (selectedRecipients.length === 0) {
      toast({ 
        title: 'Pilih warga', 
        description: 'Pilih minimal 1 warga untuk ditambahkan',
        variant: 'destructive'
      });
      return;
    }
    
    const existingNumbers = broadcastNumbers.split('\n').filter(Boolean);
    const newNumbers = selectedRecipients.map(r => r.whatsapp);
    const combined = [...new Set([...existingNumbers, ...newNumbers])];
    
    setBroadcastNumbers(combined.join('\n'));
    
    // Auto-replace variables in broadcast message if using template
    if (broadcastMessage.includes('{nama_warga}') || broadcastMessage.includes('{bulan}')) {
      // If multiple recipients, keep template as-is (will be replaced per recipient when sending)
      // User can manually customize if needed
    }
    
    setSelectedRecipients([]);
    toast({ 
      title: 'Berhasil ditambahkan', 
      description: `${newNumbers.length} nomor ditambahkan ke daftar broadcast`
    });
  };

  const handleBroadcast = async () => {
    const numbers = broadcastNumbers
      .split('\n')
      .map((n) => n.trim())
      .filter(Boolean);
    if (!numbers.length) {
      toast({ title: 'Lengkapi data', description: 'Minimal 1 nomor untuk broadcast', variant: 'destructive' });
      return;
    }
    setBroadcasting(true);
    try {
      // Create messages with variable replacement for each recipient
      const messages = numbers.map((phone) => {
        // Find recipient data
        const recipient = availableRecipients.find(r => r.whatsapp === phone) || { 
          nama_lengkap: 'Warga', 
          whatsapp: phone, 
          blok_rumah: '-' 
        };
        
        // Replace template variables
        const personalizedMessage = replaceTemplateVariables(broadcastMessage, recipient);
        
        const messagePayload = { phone, message: personalizedMessage };
        
        // Add media attachment if exists
        if (attachmentFile) {
          messagePayload.media = attachmentFile;
          console.log(`✅ [DEBUG] Media included for ${phone}:`, {
            filename: attachmentFile.filename,
            mimetype: attachmentFile.mimetype,
            dataSize: attachmentFile.data?.length || 0
          });
        }
        
        return messagePayload;
      });
      
      console.log('📤 [DEBUG] Broadcast payload:', {
        recipientCount: messages.length,
        hasMedia: messages[0]?.media ? '✅ YA' : '❌ TIDAK',
        firstMessage: {
          phone: messages[0]?.phone,
          messageLength: messages[0]?.message?.length,
          mediaSize: messages[0]?.media?.data?.length
        }
      });
      
      const res = await fetch(`${API_BASE_URL}/api/whatsapp/broadcast`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ messages }),
      });
      
      const data = await res.json();
      console.log('🔄 [DEBUG] Broadcast response:', {
        status: res.status,
        data: data
      });
      
      if (!res.ok) throw new Error(data.detail || 'Broadcast gagal');
      toast({ title: 'Broadcast berhasil', description: `${numbers.length} pesan dikirim` });
      console.log('✅ [SUCCESS] All messages sent with attachment');
      setBroadcastNumbers('');
      handleRemoveAttachment(); // Reset attachment
    } catch (err) {
      console.error('❌ [ERROR] Broadcast failed:', err);
      toast({ title: 'Broadcast gagal', description: err.message, variant: 'destructive' });
    } finally {
      setBroadcasting(false);
    }
  };

  const ready = status?.ready;
  const qrImage = status?.qr;
  const waEnabled = status?.wa_enabled !== false; // true jika vendor belum set off

  const statusBadge = useMemo(() => {
    if (!waEnabled) return <Badge className="bg-gray-100 text-gray-500">Non Aktif</Badge>;
    if (ready) return <Badge className="bg-emerald-100 text-emerald-700">Tersambung</Badge>;
    return <Badge className="bg-rose-100 text-rose-700">Belum tersambung</Badge>;
  }, [ready, waEnabled]);

  return (
    <div className="p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <p className="text-sm font-semibold text-cyan-600">Integrasi WhatsApp</p>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">WhatsApp Broadcaster</h1>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          {isVendor
            ? 'Kelola perangkat WhatsApp dan broadcast pesan ke warga.'
            : 'Kirim pesan dan broadcast tagihan ke warga menggunakan WhatsApp terpusat.'}
        </p>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card className="border border-gray-100 dark:border-gray-800">
          <CardHeader className="flex justify-between items-center">
            <CardTitle className="flex items-center gap-2">
              <QrCode className="h-5 w-5 text-cyan-500" />
              Status WhatsApp
            </CardTitle>
            <Button variant="ghost" size="sm" onClick={fetchStatus} disabled={loading}>
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
            </Button>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center gap-4">
              <p className="text-sm text-gray-600 dark:text-gray-400">Status perangkat</p>
              {statusBadge}
            </div>
            {isVendor ? (
              /* Vendor: tampilkan QR scan */
              <>
                {qrImage ? (
                  <div className="rounded-2xl border border-dashed border-cyan-400 p-4 bg-white">
                    <img src={qrImage} alt="QR WhatsApp" className="mx-auto w-48" />
                    <p className="mt-3 text-center text-sm text-gray-500">Scan via WhatsApp &gt; Linked Device</p>
                  </div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-emerald-400 p-4 text-center text-sm text-gray-600 dark:text-gray-300">
                    {ready ? 'Perangkat sudah aktif. Anda dapat mulai mengirim pesan.' : 'Menunggu QR terbaru dari service broadcaster.'}
                  </div>
                )}
                <div className="text-xs text-gray-500 space-y-1">
                  <p>1. Jalankan service `whatsapp-broadcaster`.</p>
                  <p>2. Buka menu ini dan scan QR memakai WhatsApp pengurus.</p>
                  <p>3. Pastikan perangkat tetap tersambung untuk otomatisasi token/tagihan.</p>
                </div>
              </>
            ) : (
              /* Non-vendor: tampilkan status terpusat */
              <div className={`rounded-2xl border border-dashed p-5 text-center ${!waEnabled ? 'border-gray-200 bg-gray-50' : ready ? 'border-emerald-400' : 'border-gray-300'}`}>
                <Smartphone className={`h-8 w-8 mx-auto mb-2 ${!waEnabled ? 'text-gray-300' : ready ? 'text-emerald-500' : 'text-gray-300'}`} />
                <p className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  {!waEnabled
                    ? 'Fitur WhatsApp sedang tidak aktif'
                    : ready ? 'WhatsApp aktif dan siap digunakan' : 'WhatsApp sedang tidak tersambung'}
                </p>
                <p className="text-xs text-gray-500 mt-1">
                  {!waEnabled
                    ? 'Fitur pengiriman WhatsApp untuk saat ini tidak tersedia.'
                    : 'Perangkat WhatsApp aktif dan siap digunakan untuk mengirim pesan.'}
                </p>
              </div>
            )}
            {status?.lastSync && (
              <p className="text-xs text-gray-500">Terakhir sinkron: {new Date(status.lastSync).toLocaleString('id-ID')}</p>
            )}
          </CardContent>
        </Card>

        <Card className="border border-gray-100 dark:border-gray-800">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Smartphone className="h-5 w-5 text-cyan-500" />
              Kirim Pesan Uji Coba
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label>Nomor WhatsApp</Label>
              <Input
                placeholder="08xxxxxxxxxx"
                value={testPhone}
                onChange={(e) => setTestPhone(e.target.value)}
                disabled={sending}
              />
            </div>
            <div className="space-y-2">
              <Label>Template Pesan (Opsional)</Label>
              <MessageTemplateSelector 
                value={testMessage}
                onChange={setTestMessage}
              />
            </div>
            <div className="space-y-2">
              <Label>Pesan</Label>
              <MessageEditor
                value={testMessage}
                onChange={setTestMessage}
                rows={6}
                disabled={sending}
                placeholder="Tulis pesan Anda di sini... Gunakan *bold* untuk tebal, _italic_ untuk miring"
              />
            </div>
            <Button className="w-full" onClick={handleSendTest} disabled={sending || !ready || !waEnabled}>
              {sending ? <Loader2 className="h-4 w-4 animate-spin" /> : !waEnabled ? 'WA Non Aktif' : 'Kirim Pesan'}
            </Button>
          </CardContent>
        </Card>
      </div>

      <Card className="border border-gray-100 dark:border-gray-800">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Megaphone className="h-5 w-5 text-cyan-500" />
            Broadcast Tagihan / Pengumuman
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-2">
            <Label>Pilih Penerima Broadcast</Label>
            <Select value={recipientFilter} onValueChange={handleRecipientFilterChange} disabled={loadingRecipients || broadcasting}>
              <SelectTrigger>
                <SelectValue placeholder="Pilih opsi..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="manual">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4" />
                    <span>Input Manual</span>
                  </div>
                </SelectItem>
                <SelectItem value="all">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4" />
                    <span>Semua Warga Aktif</span>
                  </div>
                </SelectItem>
                <SelectItem value="unpaid_ipl">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4" />
                    <span>Warga Tunggak IPL</span>
                  </div>
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          {showRecipientList && availableRecipients.length > 0 && (
            <Card className="border-2 border-cyan-100">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between mb-3">
                  <CardTitle className="text-base">
                    Pilih Warga ({selectedRecipients.length}/{filteredRecipients.length})
                  </CardTitle>
                  <Button 
                    variant="outline" 
                    size="sm" 
                    onClick={handleSelectAll}
                    className="flex items-center gap-2"
                  >
                    <CheckSquare className="h-4 w-4" />
                    {selectedRecipients.length === availableRecipients.length ? 'Batal Pilih Semua' : 'Pilih Semua'}
                  </Button>
                </div>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    type="text"
                    placeholder="Cari nama, nomor, atau blok..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10"
                  />
                </div>
              </CardHeader>
              <CardContent>
                <div className="max-h-64 overflow-y-auto space-y-2 border rounded-lg p-3 bg-[var(--rw-bg-card-alt)] dark:bg-gray-900">
                  {filteredRecipients.length > 0 ? (
                    filteredRecipients.map((recipient) => (
                      <div
                        key={recipient.id}
                        className="flex items-center space-x-3 p-2 hover:bg-white dark:hover:bg-gray-800 rounded cursor-pointer"
                        onClick={() => handleSelectRecipient(recipient)}
                      >
                        <Checkbox
                          checked={selectedRecipients.some(r => r.id === recipient.id)}
                          onCheckedChange={() => handleSelectRecipient(recipient)}
                        />
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                            {recipient.nama_lengkap}
                          </p>
                          <p className="text-xs text-gray-500">
                            {recipient.whatsapp} • {recipient.blok_rumah}
                          </p>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-8 text-gray-500">
                      <Search className="h-12 w-12 mx-auto mb-2 opacity-20" />
                      <p className="text-sm">Tidak ada warga yang sesuai dengan pencarian</p>
                    </div>
                  )}
                </div>
                <Button 
                  onClick={handleAddToList} 
                  disabled={selectedRecipients.length === 0}
                  className="w-full mt-4"
                >
                  Tambahkan {selectedRecipients.length > 0 ? `${selectedRecipients.length} Warga` : ''} ke List
                </Button>
              </CardContent>
            </Card>
          )}

          <div className="grid gap-6 lg:grid-cols-2">
            <div className="space-y-2">
              <Label>Daftar Nomor (satu baris satu nomor)</Label>
              <Textarea
                rows={8}
                placeholder={recipientFilter === 'manual' ? '0896xxxxxxx\n0812xxxxxxx' : 'Nomor akan otomatis terisi setelah memilih warga...'}
                value={broadcastNumbers}
                onChange={(e) => setBroadcastNumbers(e.target.value)}
                disabled={broadcasting || loadingRecipients}
              />
              <p className="text-xs text-gray-500">
                {loadingRecipients ? 'Memuat daftar nomor...' : 'Batas maksimal 50 pesan sekali kirim.'}
              </p>
            </div>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Template Pesan (Opsional)</Label>
                <MessageTemplateSelector 
                  value={broadcastMessage}
                  onChange={setBroadcastMessage}
                />
              </div>
              <div className="space-y-2">
                <Label>Lampiran File (Opsional)</Label>
                <div className="space-y-3">
                  {!attachmentPreview ? (
                    <div className="flex items-center gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        disabled={broadcasting || uploadingFile}
                        onClick={() => document.getElementById('attachment-file-input').click()}
                        className="flex items-center gap-2"
                      >
                        <Paperclip className="h-4 w-4" />
                        {uploadingFile ? 'Mengunggah...' : 'Pilih File'}
                      </Button>
                      <input
                        id="attachment-file-input"
                        type="file"
                        className="hidden"
                        accept=".pdf,.gif,.jpeg,.jpg,.png,.bmp,.doc,.docx,.xls,.xlsx"
                        onChange={handleFileUpload}
                        disabled={broadcasting || uploadingFile}
                      />
                      <span className="text-xs text-gray-500">PDF, Gambar, DOC, XLSX (Max 10MB)</span>
                    </div>
                  ) : (
                    <div className="border border-[var(--rw-border)] dark:border-gray-700 rounded-lg p-3 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800">
                      <div className="flex items-start gap-3">
                        <div className="flex-shrink-0">
                          {attachmentPreview.type === 'image' ? (
                            <div className="w-16 h-16 rounded overflow-hidden border border-gray-300">
                              <img src={attachmentPreview.url} alt="Preview" className="w-full h-full object-cover" />
                            </div>
                          ) : (
                            <div className="w-16 h-16 rounded bg-cyan-100 dark:bg-cyan-900 flex items-center justify-center">
                              <FileText className="h-8 w-8 text-cyan-600 dark:text-cyan-400" />
                            </div>
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                            {attachmentPreview.name}
                          </p>
                          {attachmentPreview.size && (
                            <p className="text-xs text-gray-500">{attachmentPreview.size}</p>
                          )}
                          {attachmentPreview.type === 'image' && (
                            <p className="text-xs text-cyan-600 dark:text-cyan-400">✓ Gambar siap dikirim</p>
                          )}
                        </div>
                        <Button
                          type="button"
                          variant="ghost"
                          size="sm"
                          onClick={handleRemoveAttachment}
                          disabled={broadcasting}
                          className="flex-shrink-0"
                        >
                          <X className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
              <div className="space-y-2">
                <Label>Pesan Broadcast</Label>
                <MessageEditor
                  value={broadcastMessage}
                  onChange={setBroadcastMessage}
                  rows={8}
                  disabled={broadcasting}
                  placeholder="Tulis pesan broadcast Anda..."
                />
              </div>
              <Button onClick={handleBroadcast} disabled={broadcasting || !ready || !waEnabled} className="w-full">
                {broadcasting ? <Loader2 className="h-4 w-4 animate-spin" /> : !waEnabled ? 'WA Non Aktif' : 'Kirim Broadcast'}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export default WhatsAppIntegrationPage;
