import React, { useState, useEffect, useCallback, useRef } from 'react';
import { API_ENDPOINTS } from '@/config/api';
import { Stars } from '@/components/Stars';
import { CardImageStrip } from '@/components/ImageGallery';
import ListingForm from '@/components/ListingForm';
import DetailModal from '@/components/DetailModal';
import { useToast } from '@/components/Toast';
import { useTheme } from '@/contexts/ThemeContext';
import ApiErrorBanner from '@/components/ApiErrorBanner';
import './YellowPage.css';
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { useAuth } from "@/contexts/AuthContext";
import { AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogFooter, AlertDialogTitle, AlertDialogOverlay ,AlertDialogCancel, AlertDialogAction, AlertDialogPortal } from "@/components/ui/alert-dialog";


/* ── Constants ──────────────────────────────────────────────── */
const SOC_ICONS = {
  instagram: '📸', facebook: '👍', tiktok: '🎵', twitter: '🐦', youtube: '▶️',
};
const SOC_KEYS = ['instagram', 'facebook', 'tiktok', 'twitter', 'youtube'];

/* ── Helpers ────────────────────────────────────────────────── */
function getCatIcon(name, cats) {
  return cats.find(c => c.nama === name)?.icon || '📌';
}

/* ── Social strip ───────────────────────────────────────────── */
function SocialStrip({ item }) {
  const hasSoc = SOC_KEYS.some(k => item[k]);
  if (!hasSoc) return null;
  return (
    <div className="social-strip">
      {SOC_KEYS.filter(k => item[k]).map(k => (
        <span key={k} className="soc-icon" title={k}>{SOC_ICONS[k]}</span>
      ))}
    </div>
  );
}

/* ── Listing Card — uniform height ──────────────────────────── */
function ListingCard({ item, cats, onClick, delay = 0 }) {
  const icon = getCatIcon(item.kategori, cats);
  return (
    <div className="listing-card" style={{ animationDelay: `${delay}s` }} onClick={onClick}>
      <SocialStrip item={item} />
      <div className="card-body">
        <div className="card-top">
          <div className="card-avatar">{icon}</div>
          <div className="card-meta-top">
            <div className="card-name" title={item.nama}>{item.nama}</div>
            {item.nama_pemilik && (
              <div className="card-owner">
                👤 {item.nama_pemilik}{item.no_rumah ? ` · ${item.no_rumah}` : ''}
              </div>
            )}
            <div className="card-badges">
              <span className="badge badge-cat">{icon} {item.kategori}</span>
              <span className={`badge ${item.aktif ? 'badge-active' : 'badge-inactive'}`}>
                {item.aktif ? '✓ Aktif' : 'Non Aktif'}
              </span>
            </div>
          </div>
        </div>

        <div className="card-desc">{item.deskripsi || '\u00A0'}</div>

        <div className="card-info">
          <div className="card-info-row">
            {item.total_reviews > 0
              ? <Stars rating={item.avg_rating} count={item.total_reviews} />
              : <>
                  <span className="ci-icon">⭐</span>
                  <span style={{ color: 'var(--text-3)', fontSize: 11 }}>Belum ada ulasan</span>
                </>
            }
          </div>
          <div className="card-info-row">
            <span className="ci-icon">📞</span>
            <span>{item.telepon || '–'}</span>
          </div>
          <div className="card-info-row">
            <span className="ci-icon">🕒</span>
            <span>{item.jam_operasional || '–'}</span>
          </div>
          <div className="card-info-row">
            <span className="ci-icon">📍</span>
            <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {item.alamat || '–'}
            </span>
          </div>
        </div>
      </div>

      {/* Image strip — shown only if images exist */}
      {item.images && item.images.length > 0 && (
        <CardImageStrip
          images={item.images}
          onClick={onClick}
        />
      )}

      <div className="card-footer">
        {item.whatsapp && (
          <a
            href={`https://wa.me/${item.whatsapp}`}
            target="_blank"
            rel="noopener noreferrer"
            className="btn btn-wa"
            onClick={e => e.stopPropagation()}
          >
            💬 WA
          </a>
        )}
        {item.telepon && (
          <a
            href={`tel:${item.telepon}`}
            className="btn btn-tel"
            onClick={e => e.stopPropagation()}
          >
            📞 Telp
          </a>
        )}
        <button className="btn btn-secondary" style={{ marginLeft: 'auto' }}>
          Lihat Detail →
        </button>
      </div>
    </div>
  );
}

/* ── Category Dropdown ──────────────────────────────────────── */
function CategoryDropdown({ categories, activeCategory, catCounts, onSelect }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const activeCat  = categories.find(c => c.nama === activeCategory);
  const totalCount = Object.values(catCounts).reduce((a, b) => a + b, 0);

  return (
    <div className="cat-dropdown-wrap" ref={ref}>
      <button
        className={`cat-dropdown-btn ${open ? 'open' : ''}`}
        onClick={() => setOpen(v => !v)}
      >
        <span>{activeCat ? `${activeCat.icon} ${activeCat.nama}` : '🗂️ Semua Kategori'}</span>
        <span className="chevron">▼</span>
      </button>

      {open && (
        <div className="cat-dropdown-menu">
          <div
            className={`cat-dropdown-item ${activeCategory === '' ? 'active' : ''}`}
            onClick={() => { onSelect(''); setOpen(false); }}
          >
            <span className="di-icon">🗂️</span>
            <span>Semua Kategori</span>
            <span className="di-count">{totalCount}</span>
          </div>
          <div className="cat-dropdown-divider" />
          {categories.map(cat => (
            <div
              key={cat.id}
              className={`cat-dropdown-item ${activeCategory === cat.nama ? 'active' : ''}`}
              onClick={() => { onSelect(cat.nama); setOpen(false); }}
            >
              <span className="di-icon">{cat.icon}</span>
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {cat.nama}
              </span>
              {catCounts[cat.nama] && (
                <span className="di-count">{catCounts[cat.nama]}</span>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ── Main YellowPage ────────────────────────────────────────── */
export default function YellowPage() {
  const { theme, toggle: toggleTheme } = useTheme();
  const { show } = useToast();

  const [listings, setListings]         = useState([]);
  const [categories, setCategories]     = useState([]);
  const [stats, setStats]               = useState({ total_listings: 0, total_reviews: 0, by_category: [], top_rated: [] });
  const [loading, setLoading]           = useState(true);
  const [total, setTotal]               = useState(0);
  const [search, setSearch]             = useState('');
  const [debouncedSearch, setDebounced] = useState('');
  const [activeCategory, setActiveCat]  = useState('');
  const [sort, setSort]                 = useState('nama');
  const [view, setView]                 = useState('grid');
  const [page, setPage]                 = useState(0);
  const [showForm, setShowForm]         = useState(false);
  const [editItem, setEditItem]         = useState(null);
  const [detailItem, setDetailItem]     = useState(null);
  const [sidebarOpen, setSidebarOpen]   = useState(false);
  const [apiError, setApiError]         = useState(null);

  const LIMIT       = 20;
  const searchTimer = useRef(null);

  const { token, logout, user } = useAuth(); // 🔥 AMBIL TOKEN & USER
  const { canCreate, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);

  const [openDeleteListing, setOpenDeleteListing] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);

  const handleSearchChange = (val) => {
    setSearch(val);
    clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => { setDebounced(val); setPage(0); }, 350);
  };

  const loadListings = useCallback(async () => {
    setLoading(true);
    try {
      const res = await API_ENDPOINTS.getListings({
        search: debouncedSearch,
        kategori: activeCategory,
        sort,
        skip: page * LIMIT,
        limit: LIMIT,
      });
      setListings(res.data);
      setTotal(res.total);
      setApiError(null);
    } catch (e) {
      setApiError(e.message);
      show('Gagal memuat data', 'error');
    }
    setLoading(false);
  }, [debouncedSearch, activeCategory, sort, page]);

  const refreshListings = async () => {
    try {     
        const res = await API_ENDPOINTS.getListings({
          search: debouncedSearch,
          kategori: activeCategory,
          sort,
          skip: page * LIMIT,
          limit: LIMIT,
        });
          
     setListings(res.data); 
     setTotal(res.total);
     } catch (e) {
      setApiError(e.message);
      show('Gagal memuat data', 'error');
     }
  }


  const loadCategories = useCallback(async () => {
    try {
      setCategories(await API_ENDPOINTS.getCategories());
      setApiError(null);
    } catch (e) {
      setApiError(e.message);
    }
  }, []);

  const loadStats = useCallback(async () => {
    try { setStats(await API_ENDPOINTS.getStats()); } catch {}
  }, []);

  useEffect(() => { loadListings(); }, [loadListings]);
  useEffect(() => { loadCategories(); loadStats(); }, []);

  // Category counts map
  const catCounts = {};
  stats.by_category.forEach(c => { catCounts[c.kategori] = c.count; });

  const handleSave = async (data) => {
    try {
      let savedId = editItem?.id;
      if (editItem) {
        await API_ENDPOINTS.updateListing(editItem.id, data);
        show('Listing diperbarui! ✓', 'success');
      } else {
        const res = await API_ENDPOINTS.createListing(data);
        savedId = res.id;
        show('Listing ditambahkan! ✓', 'success');
      }
     /*  setShowForm(false);
      setEditItem(null);
      loadListings();
      await refreshListings(); // Refresh listings to get updated review counts and ratings
      loadStats(); */
      return { id: savedId };   // ← returned to ListingForm for image upload
    } catch (e) {
      show(e.message || 'Gagal menyimpan', 'error');
      throw e;
    }
  };

  const handleEdit = (item) => {
    setEditItem(item);
    setDetailItem(null);
    setShowForm(true);
  };

  const confirmDeleteListing = async () => {
  if (!selectedItem) return;

  try {
    await API_ENDPOINTS.deleteListing(selectedItem.id);
    show('Listing dihapus', 'success');

    setOpenDeleteListing(false);
    setSelectedItem(null);
    setDetailItem(null);

    loadListings();
    loadStats();
  } catch {
    show('Gagal menghapus', 'error');
  }
};

  const handleDelete = (item) => {
  setSelectedItem(item);
  setOpenDeleteListing(true);
 };

 
  const selectCategory = (nama) => {
    setActiveCat(nama);
    setPage(0);
    setSidebarOpen(false);
  };

  const totalPages = Math.ceil(total / LIMIT);

  return (
    <>
      {/* Mobile backdrop */}
      <div
        className={`sidebar-backdrop ${sidebarOpen ? 'open' : ''}`}
        onClick={() => setSidebarOpen(false)}
      />

      {/* Topbar */}
      <div className="topbar">
      
        <div className="topbar-left">
          <div className="topbar-title">
            <h1>📒 Yellow Pages</h1>
            <p>Direktori internal warga KBBS</p>
          </div>
        </div>

        {/* Category dropdown */}
        <CategoryDropdown
          categories={categories}
          activeCategory={activeCategory}
          catCounts={catCounts}
          onSelect={selectCategory}
        />

       

        <div className="topbar-actions">
        {canCreate('yellow-page') && (
          <button
            className="btn btn-primary"
            onClick={() => { setEditItem(null); setShowForm(true); }}
          >
            <span>➕</span> Tambah
          </button>
        )}
        </div>
      </div>

      {/* Page body */}
      <div className="page-body">

        {/* API Error Banner */}
        <ApiErrorBanner
          error={apiError}
          onRetry={() => { loadListings(); loadCategories(); loadStats(); }}
        />

        {/* Stats */}
        <div className="stats-row">
          <div className="stat-card">
            <div className="stat-icon">📋</div>
            <div>
              <div className="stat-val">{stats.total_listings}</div>
              <div className="stat-lbl">Total Listing Aktif</div>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">🗂️</div>
            <div>
              <div className="stat-val">{stats.by_category.length}</div>
              <div className="stat-lbl">Kategori Aktif</div>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">⭐</div>
            <div>
              <div className="stat-val">{stats.total_reviews}</div>
              <div className="stat-lbl">Total Ulasan</div>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">🏆</div>
            <div>
              <div className="stat-val" style={{ fontSize: 13, fontFamily: 'DM Sans', fontWeight: 700 }}>
                {stats.top_rated[0]?.nama || '–'}
              </div>
              <div className="stat-lbl">Rating Tertinggi</div>
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-icon">🚫</div>
            <div>
              <div className="stat-val">{stats.total_listings_noaktif}</div>
              <div className="stat-lbl">Total Listing Non Aktif</div>
            </div>
          </div>
        </div>

         {/* Search */}
        <div className="topbar-search">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
            <circle cx="11" cy="11" r="8" />
            <path d="m21 21-4.35-4.35" />
          </svg>
          <input
            type="text"
            placeholder="Cari nama, pemilik, tag..."
            value={search}
            onChange={e => handleSearchChange(e.target.value)}
          />
        </div>

        {/* Toolbar */}
        <div className="toolbar">
          <select
            className="sort-select"
            value={sort}
            onChange={e => { setSort(e.target.value); setPage(0); }}
          >
            <option value="nama">Urut: A–Z</option>
            <option value="rating">Urut: Rating Tertinggi</option>
            <option value="newest">Urut: Terbaru</option>
          </select>

          {activeCategory && (
            <div className="filter-badge">
              {getCatIcon(activeCategory, categories)} {activeCategory}
              <button onClick={() => selectCategory('')}>×</button>
            </div>
          )}

          <span className="result-count">{total} listing ditemukan</span>

          <div className="view-toggle">
            <button className={view === 'grid' ? 'active' : ''} onClick={() => setView('grid')}>⊞</button>
            <button className={view === 'table' ? 'active' : ''} onClick={() => setView('table')}>☰</button>
          </div>
        </div>

        {/* Listings */}
        {loading ? (
          <div className="loading-center"><div className="spinner" /></div>
        ) : listings.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">🗂️</div>
            <h3>Tidak ada listing</h3>
            <p>
              {debouncedSearch || activeCategory
                ? 'Coba kata kunci atau kategori lain'
                : 'Mulai tambahkan listing pertama'}
            </p>
            {!debouncedSearch && (
              <button
                className="btn btn-primary"
                style={{ marginTop: 8 }}
                onClick={() => { setEditItem(null); setShowForm(true); }}
              >
                ➕ Tambah Listing
              </button>
            )}
          </div>
        ) : view === 'grid' ? (
          <div className="listings-grid">
            {listings.map((item, i) => (
              <ListingCard
                key={item.id}
                item={item}
                cats={categories}
                onClick={() => setDetailItem(item)}
                delay={i * 0.035}
              />
            ))}
          </div>
        ) : (
          <div style={{ width: '100%', overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Nama Usaha</th>
                  <th>Kategori</th>
                  <th>No. Rumah / Kantor</th>
                  <th>Telepon</th>
                  <th>Rating</th>
                  <th>Jam Buka</th>
                  <th>Status</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {listings.map(item => (
                  <tr key={item.id} onClick={() => setDetailItem(item)}>
                    <td>
                      <div className="td-name-main">
                        {getCatIcon(item.kategori, categories)} {item.nama}
                      </div>
                      {item.nama_pemilik && (
                        <div className="td-sub">👤 {item.nama_pemilik}</div>
                      )}
                    </td>
                    <td><span className="badge badge-cat">{item.kategori}</span></td>
                    <td>{item.no_rumah || '–'}</td>
                    <td>{item.telepon || '–'}</td>
                    <td>
                      {item.avg_rating > 0
                        ? <Stars rating={item.avg_rating} count={item.total_reviews} />
                        : <span style={{ color: 'var(--text-3)', fontSize: 12 }}>–</span>
                      }
                    </td>
                    <td>{item.jam_operasional || '–'}</td>
                    <td>
                      <span className={`badge ${item.aktif ? 'badge-active' : 'badge-inactive'}`}>
                        {item.aktif ? '✓ Aktif' : 'Non Aktif'}
                      </span>
                    </td>
                    {canEdit('yellow-page') && (
                    <td onClick={e => e.stopPropagation()}>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => handleEdit(item)}
                      >
                        ✏️
                      </button>
                    </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
         
          </div>
          </div>
        )}

        {/* BULK DELETE CONFIRMATION */}
        <AlertDialog open={openDeleteListing} onOpenChange={setOpenDeleteListing}>
          <AlertDialogPortal container={document.body}>
    
          <AlertDialogOverlay className="fixed inset-0 bg-black/60 z-[9998]" />
          
          <AlertDialogContent className="fixed z-[9999]">
      
            <AlertDialogHeader>
              <AlertDialogTitle>
                Hapus "{selectedItem?.nama}"?
              </AlertDialogTitle>
              <p className="text-sm text-gray-500">
                Data listing akan dihapus permanen.
              </p>
            </AlertDialogHeader>

            <AlertDialogFooter>
              <AlertDialogCancel>Batal</AlertDialogCancel>

              <AlertDialogAction
                className="bg-red-600 hover:bg-red-700 text-white"
                onClick={confirmDeleteListing}
              >
                Hapus
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
          </AlertDialogPortal>
        </AlertDialog>

        {/* Pagination */}
        {total > LIMIT && (
          <div className="pagination">
            <div className="pagination-info">
              {page * LIMIT + 1}–{Math.min((page + 1) * LIMIT, total)} dari {total} listing
            </div>
            <div className="pagination-btns">
              <button
                className="btn btn-secondary btn-sm"
                disabled={page === 0}
                onClick={() => setPage(p => p - 1)}
              >
                ← Sebelumnya
              </button>
              <button
                className="btn btn-secondary btn-sm"
                disabled={page >= totalPages - 1}
                onClick={() => setPage(p => p + 1)}
              >
                Selanjutnya →
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Modals */}
      {showForm && (
        <ListingForm
          initial={editItem}
  categories={categories}
  onSave={handleSave}
  onAfterSave={async () => {
    setShowForm(false);
    setEditItem(null);

    await loadListings();  // ⬅️ reload setelah upload selesai
    await loadStats();
  }}
  onClose={() => {
    setShowForm(false);
    setEditItem(null);
  }}
        />
      )}

      {detailItem && (
        <DetailModal
          item={detailItem}
          categories={categories}
          onClose={() => setDetailItem(null)}
          onEdit={handleEdit}
          onDelete={handleDelete}
        />
      )}
    </>
  );
}
