// Segmen pertama URL yang merupakan rute aplikasi asli (bukan slug kelurahan).
// HARUS disamakan dengan RESERVED_SLUGS di backend/vendor.py — vendor tidak
// bisa membuat slug dari kata-kata ini, jadi selama daftar ini konsisten,
// tidak akan ada slug kelurahan yang "ketutupan" oleh rute aplikasi asli.
const KNOWN_TOP_SEGMENTS = new Set([
  'login', 'lupa-password', 'register', 'vendor-login', 'verify-surat',
  'vendor', 'api', 'uploads', 'static',
  'whatsapp', 'configuration', 'profil-rt', 'tarif-ipl', 'management',
  'warga', 'users', 'user-permissions', 'roles', 'finance', 'dana',
  'operational', 'environment', 'karyawan', 'rumah', 'kartu-keluarga',
  'keuangan', 'kasbon', 'laporan', 'rekening', 'surat', 'surat-resmi',
  'ajukan-surat', 'ipl', 'pengumuman', 'notifikasi', 'informasi',
  'pengaduan', 'tamu-lapor', 'panic-alerts', 'agenda', 'aktivitas-log',
  'data-management', 'help', 'budget', 'yellow-pages', 'cek-bansos',
  'sp4n-lapor', 'cctv', 'cctv-config', 'subscription',
  'rw', 'rt', 'kelurahan', 'dashboard',
]);

// Deteksi slug kelurahan dari URL awal saat app pertama kali dimuat — kalau
// segmen pertama path BUKAN salah satu rute aplikasi di atas, dianggap slug
// kelurahan dan dipakai sebagai `basename` BrowserRouter (lihat App() di
// bawah). Dengan basename aktif, SEMUA navigate()/<Link>/<Navigate> yang
// sudah ada di seluruh app (path absolut spt "/rw/dashboard") otomatis
// tetap membawa prefix "/{slug}" tanpa perlu diubah satu per satu.
function computeSlugBasename() {
  const seg = window.location.pathname.split('/').filter(Boolean)[0];
  if (!seg) return null;
  if (KNOWN_TOP_SEGMENTS.has(seg.toLowerCase())) return null;
  return `/${seg}`;
}

// Route "/" — kalau BrowserRouter sedang jalan dengan basename "/{slug}"
// (lihat computeSlugBasename di bawah), path "/" ini sebenarnya "/{slug}/"
// di address bar: pengunjung anonim melihat halaman login ber-slug, yang
// sudah login langsung ke dashboard. Tanpa basename (mode biasa), pengunjung
// anonim melihat landing page umum.
const RootRoute = ({ slug }) => {
  const { user, isLoading } = useAuth();

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="text-gray-600 dark:text-gray-400">Memuat...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return slug ? <TenantLoginPage slug={slug} /> : <LandingPage />;
  }

  return (
    <ProtectedRoute menuId="dashboard">
      <MainLayout>
        <HomeRedirect />
      </MainLayout>
    </ProtectedRoute>
  );
};

// Route "/" yang redirect ke dashboard sesuai role
const HomeRedirect = () => {
  const { user } = useAuth();
  if (['pengurus_kelurahan', 'kelurahan', 'staff_kelurahan'].includes(user?.role)) return <Navigate to="/kelurahan/dashboard" replace />;
  if (['pengurus_rw', 'rw'].includes(user?.role)) return <Navigate to="/rw/dashboard" replace />;
  return <Dashboard />;
};

// Protected Route Component with permission checking
const ProtectedRoute = ({ children, menuId = null }) => {
  const { user, isLoading, token } = useAuth();
  const tenantProfile = useTenantProfile(token);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="text-gray-600 dark:text-gray-400">Memuat...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  // Paksa URL selalu memakai slug kelurahan milik sesi yang login — mencegah
  // akses lewat slug kelurahan lain (nyasar/salah sesi) atau tanpa slug sama
  // sekali. Redirect ini hard-navigation (bukan Navigate biasa) karena
  // basename BrowserRouter cuma dihitung sekali saat app dimuat (lihat
  // computeSlugBasename di atas) — ganti slug butuh reload penuh.
  if (tenantProfile && tenantProfile.kelurahan_slug) {
    const currentSlug = computeSlugBasename();
    const expectedSlug = `/${tenantProfile.kelurahan_slug}`;
    if (currentSlug !== expectedSlug) {
      const appPath = currentSlug
        ? (window.location.pathname.slice(currentSlug.length) || '/')
        : window.location.pathname;
      window.location.replace(`${expectedSlug}${appPath}${window.location.search}`);
      return (
        <div className="min-h-screen flex items-center justify-center">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin"></div>
        </div>
      );
    }
  }

  // If menuId specified, check read permission from local permissions matrix
  if (menuId && !hasPermission(user.role, menuId, 'read')) {
    // Redirect to users page if dashboard not accessible
    if (menuId === 'dashboard') {
      return <Navigate to="/users" replace />;
    }
    return <Navigate to="/" replace />;
  }

  return children;
};

// Main Layout Component
const MainLayout = ({ children }) => {
  const { user, token } = useAuth();
  const [panicCount, setPanicCount] = React.useState(0);
  const [notifDismissed, setNotifDismissed] = React.useState(false);
  const { bannerConfig } = useAppSettings();

  const { needsPermission, enableNotifications } = useFCM(user, token);

  const handleEnableNotif = async () => {
    const ok = await enableNotifications();
    if (!ok) setNotifDismissed(true);
  };

  const showDashboardBanner = ['admin', 'pengurus_rw', 'pengurus_kelurahan', 'warga'].includes(user?.role);
  const bannerAtBottom = bannerConfig?.dashboardPosition === 'bottom';

  return (
    <SearchProvider>
      <SidebarProvider>
        <div className="flex h-screen overflow-hidden bg-[var(--rw-bg-page)] dark:bg-gray-900">
          <Sidebar />
          <div className="flex-1 flex flex-col overflow-hidden">
            {/* Banner aktifkan notifikasi — admin, RW, kelurahan, dan warga */}
            {needsPermission && !notifDismissed && (
              <NotificationPermissionBanner
                onEnable={handleEnableNotif}
                onDismiss={() => setNotifDismissed(true)}
                role={user?.role}
              />
            )}
            {/* Panic Alert Banner — hanya admin */}
            <PanicAlertBanner count={panicCount} />
            {/* Notifikasi vendor — banner teks pengumuman dari vendor (RT/RW/Kel) */}
            <VendorAnnouncementBanner />
            <Header panicCount={panicCount} onPanicCountChange={setPanicCount} />
            <main
              className="flex-1 overflow-y-auto"
              style={bannerAtBottom ? { paddingBottom: (bannerConfig?.dashboardHeight || 160) + 32 } : undefined}
            >
              {/* Banner dashboard posisi Top — sticky di atas area scroll (bukan statis
                  di luar alur), jadi konten yang di-scroll lewat di baliknya kelihatan
                  sekilas lewat sisi kiri/kanan yang transparan (mode Fit). */}
              {showDashboardBanner && !bannerAtBottom && (
                <div className="sticky top-0 z-30 px-4 pt-3 pb-1">
                  <VendorImageBanner variant="dashboard" />
                </div>
              )}
              <SubscriptionGate>
                {children}
              </SubscriptionGate>
            </main>
            {/* Banner dashboard posisi Bottom — DIPAKSA fixed relatif ke viewport
                (bukan sticky di dalam main), supaya selalu nempel di bawah layar
                walaupun isi halaman pendek/belum penuh satu layar. Kalau dipakai
                sticky di dalam main, banner ikut naik saat konten kurang dari
                tinggi layar — makanya di sini pakai fixed, bukan sticky. */}
            {showDashboardBanner && bannerAtBottom && (
              <div className="fixed bottom-0 left-0 lg:left-64 right-0 z-40 px-4 pb-3 pt-2">
                <VendorImageBanner variant="dashboard" />
              </div>
            )}
          </div>
          {/* Floating Panic Button — global untuk semua user */}
          <PanicButton />
          {/* Floating Support Chat Button — khusus admin RT/RW/Kelurahan */}
          <SupportChatButton />
        </div>
      </SidebarProvider>
    </SearchProvider>
  );
};

