// Session Expired Dialog Component
const SessionExpiredDialog = () => {
  const { showSessionExpired, setShowSessionExpired } = useAuth();

  return (
    <AlertDialog open={showSessionExpired} onOpenChange={setShowSessionExpired}>
      <AlertDialogContent className="dark:bg-gray-900 dark:text-gray-100 max-w-md">
        <AlertDialogHeader>
          <AlertDialogTitle className="text-xl font-bold text-red-600 dark:text-red-400">
            Sesi Berakhir
          </AlertDialogTitle>
        </AlertDialogHeader>
        <div className="space-y-3">
          <p className="text-gray-600 dark:text-gray-300 text-sm">
            Session Anda telah berakhir karena tidak ada aktivitas dalam waktu yang lama.
          </p>
          <p className="text-gray-600 dark:text-gray-300 text-sm font-semibold">
            Silakan login kembali untuk melanjutkan.
          </p>
        </div>
        <AlertDialogFooter className="mt-6">
          <AlertDialogAction
            onClick={() => {
              setShowSessionExpired(false);
              window.location.href = getLoginPath();
            }}
            className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white font-semibold px-6"
          >
            Login Kembali
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
};

function App() {
  // Dihitung sekali dari URL awal saat load — basename tetap stabil sepanjang
  // sesi SPA (tidak dihitung ulang tiap render), sesuai cara kerja prop
  // `basename` react-router.
  const [basename] = useState(() => computeSlugBasename());
  const slug = basename ? basename.slice(1) : null;

  return (
    <AppSettingsProvider>
    <ColorThemeProvider slug={slug}>
    <ThemeProvider>
      <AuthProvider>
      <TenantProvider>
      <RWFilterProvider>
      <KelurahanFilterProvider>
      <TenantFeatureProvider>
        <BrowserRouter basename={basename || undefined}>
          <AppRoutes slug={slug} />
          <Toaster />
          <SessionExpiredDialog />
        </BrowserRouter>
      </TenantFeatureProvider>
      </KelurahanFilterProvider>
      </RWFilterProvider>
      </TenantProvider>
    </AuthProvider>
    </ThemeProvider>
    </ColorThemeProvider>
    </AppSettingsProvider>
  );
}

export default App;