import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { API_BASE_URL, API_ENDPOINTS } from '../config/api';
import {
  Building2,
  Twitter, Facebook, Youtube, Instagram, Music2, MessageCircle,
} from 'lucide-react';
import { toast } from '../hooks/use-toast';
import { useAuth } from '../contexts/AuthContext';
import { useAppSettings } from '../contexts/AppSettingsContext';
import { setStoredTenantSlug } from '../lib/tenantSlug';
import defaultLogo from '../assets/images/logo.png';
import LOGIN_LAYOUTS from './loginLayouts';

const SOCIAL_ICONS = [
  { key: 'twitter',   label: 'Twitter / X', Icon: Twitter },
  { key: 'facebook',  label: 'Facebook',    Icon: Facebook },
  { key: 'youtube',   label: 'YouTube',     Icon: Youtube },
  { key: 'instagram', label: 'Instagram',   Icon: Instagram },
  { key: 'tiktok',    label: 'TikTok',      Icon: Music2 },
  { key: 'discord',   label: 'Discord',     Icon: MessageCircle },
];

// Halaman login ber-slug per kelurahan — dirender di path "/login" saat
// BrowserRouter (App.js) sedang jalan dengan basename "/{slug}", jadi di
// address bar tetap tampil "/{slug}/login". `slug` diberikan sebagai prop
// dari App.js (bukan useParams — path route-nya sendiri sekarang cuma
// "/login", basename yang membawa slug-nya). Tampilan sama persis dengan
// LoginPage.jsx standar, hanya branding (logo, judul, deskripsi, warna) yang
// diambil dari GET /api/tenant/branding/{slug} (endpoint publik) alih-alih
// dari AppSettings global. Komponen ini sengaja terpisah dari LoginPage.jsx
// (bukan wrapper-nya) supaya perubahan di sini tidak berisiko terhadap alur
// login utama yang dipakai semua role dan traffic-nya jauh lebih tinggi.
const TenantLoginPage = ({ slug: kelurahanSlug }) => {
  const navigate = useNavigate();
  const { setAuthUser } = useAuth();
  const { appName: vendorAppName } = useAppSettings();

  const [branding, setBranding] = useState(null);
  const [loadingBranding, setLoadingBranding] = useState(true);
  const [notFound, setNotFound] = useState(false);

  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoadingBranding(true);
    setNotFound(false);
    fetch(API_ENDPOINTS.TENANT_BRANDING(kelurahanSlug))
      .then((res) => {
        if (res.status === 404) {
          if (!cancelled) setNotFound(true);
          return null;
        }
        return res.json();
      })
      .then((data) => {
        if (!cancelled && data) setBranding(data);
      })
      .catch(() => {
        if (!cancelled) setNotFound(true);
      })
      .finally(() => {
        if (!cancelled) setLoadingBranding(false);
      });
    return () => { cancelled = true; };
  }, [kelurahanSlug]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      const res = await fetch(`${API_BASE_URL}/api/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          whatsapp: phone,
          password,
          tenant_slug: kelurahanSlug,
        }),
      });

      const responseText = await res.text();
      let data = {};
      try {
        data = JSON.parse(responseText);
      } catch (e) {
        data = {};
      }

      if (res.status === 401) {
        setError('No WhatsApp atau password salah');
        return;
      }
      if (res.status === 403) {
        setError(data.detail || 'Akun ini tidak terdaftar di kelurahan ini');
        return;
      }
      if (res.status === 404) {
        setError('Halaman kelurahan tidak ditemukan');
        return;
      }
      if (!res.ok) {
        setError(data.detail || 'Terjadi kesalahan, silakan coba lagi');
        return;
      }

      const expireAt = Date.now() + 30 * 60 * 1000;
      const authUser = {
        id: data.user.id,
        fullname: data.user.fullname,
        username: data.user.username || '',
        whatsapp: data.user.whatsapp,
        role: data.user.role,
        block_house: data.user.block_house || '',
        tenant_id: data.user.tenant_id || null,
      };
      setStoredTenantSlug(kelurahanSlug);
      setAuthUser(authUser, data.access_token, expireAt);

      toast({ title: 'Login Berhasil', description: `Selamat datang di ${branding?.name || 'Ruang Warga'}` });

      const ROLE_HOME = {
        admin: '/',
        warga: '/',
        karyawan: '/users',
        staff: '/users',
        pengurus_rw: '/rw/dashboard',
        pengurus_kelurahan: '/kelurahan/dashboard',
        staff_kelurahan: '/kelurahan/dashboard',
      };
      navigate(ROLE_HOME[data.user.role] ?? '/');
    } catch (err) {
      console.error('Tenant login error:', err);
      setError('Tidak dapat terhubung ke server');
    } finally {
      setIsLoading(false);
    }
  };

  if (loadingBranding) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[var(--rw-bg-page)] dark:bg-gray-950">
        <div className="w-10 h-10 border-4 border-[var(--rw-primary)] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (notFound) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-4 bg-[var(--rw-bg-page)] dark:bg-gray-950 text-center px-6">
        <Building2 className="w-12 h-12 text-gray-300" />
        <h1 className="text-xl font-bold text-gray-800 dark:text-white">Halaman tidak ditemukan</h1>
        <p className="text-gray-500 dark:text-gray-400 max-w-sm">
          Link kelurahan ini tidak valid atau sudah tidak aktif.
        </p>
        {/* Hard link (bukan <Link>) dengan sengaja — kalau slug di URL ini
            palsu/tidak valid, dia jadi basename BrowserRouter (lihat
            computeSlugBasename di App.js), jadi <Link to="/"> yang
            basename-aware akan balik ke basename itu sendiri, bukan ke
            root aplikasi yang sebenarnya. href absolut + reload penuh
            memastikan benar-benar keluar dari basename yang salah. */}
        <a href="/" className="text-[var(--rw-primary)] font-semibold hover:underline">
          Kembali ke beranda
        </a>
      </div>
    );
  }

  const logo = branding?.logo_url ? `${API_BASE_URL}${branding.logo_url}` : defaultLogo;
  const appTitle = branding?.name || 'Ruang Warga';
  const appDescription = branding?.welcome_text
    || 'Digitalisasi informasi, Komunikasi dan Administrasi Yang Terintegrasi Untuk Tingkat RT, RW, dan Kelurahan/Desa';
  const primaryColorStyle = branding?.primary_color
    ? { '--rw-primary': branding.primary_color, '--rw-primary-hover': branding.primary_color }
    : undefined;

  // Tata letak (tema login) dipilih Kelurahan lewat Konfigurasi > Setting,
  // dari daftar yang dipublish vendor (lihat backend/app_settings.py
  // LOGIN_LAYOUT_PRESETS). "default" = tampilan diagonal bawaan.
  const LayoutComponent = LOGIN_LAYOUTS[branding?.login_layout_id] || LOGIN_LAYOUTS.default;

  return (
    <LayoutComponent
      branding={branding}
      logo={logo}
      appTitle={appTitle}
      appDescription={appDescription}
      vendorAppName={vendorAppName}
      primaryColorStyle={primaryColorStyle}
      phone={phone}
      setPhone={setPhone}
      password={password}
      setPassword={setPassword}
      error={error}
      isLoading={isLoading}
      handleSubmit={handleSubmit}
      navigate={navigate}
      SOCIAL_ICONS={SOCIAL_ICONS}
    />
  );
};

export default TenantLoginPage;
