import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { API_BASE_URL } from '../../config/api';
import { Lock, MessageCircle, Eye, EyeOff } from 'lucide-react';

const TAGLINES = [
  'Kelola RT/RW lebih mudah.',
  'Iuran warga, terorganisir.',
  'Data kependudukan digital.',
  'Surat menyurat, satu klik.',
  'Warga terhubung, RT aman.',
];

const COLORS = [
  '#ed6f5c', '#f4a261', '#e9c46a', '#2a9d8f',
  '#457b9d', '#a8dadc', '#e76f51', '#81b29a',
  '#f2cc8f', '#6a4c93', '#1982c4', '#8ac926',
];

function ParticleCanvas() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    let animId;

    const resize = () => {
      canvas.width  = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener('resize', resize);

    // Create particles
    const COUNT = 90;
    const particles = Array.from({ length: COUNT }, () => ({
      x:     Math.random() * canvas.width,
      y:     Math.random() * canvas.height,
      r:     Math.random() * 3.5 + 1.2,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
      vx:    (Math.random() - 0.5) * 0.6,
      vy:    (Math.random() - 0.5) * 0.6,
      alpha: Math.random() * 0.5 + 0.3,
      pulse: Math.random() * Math.PI * 2,
      pulseSpeed: Math.random() * 0.02 + 0.008,
    }));

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.pulse += p.pulseSpeed;

        // Wrap around edges
        if (p.x < -10) p.x = canvas.width + 10;
        if (p.x > canvas.width + 10) p.x = -10;
        if (p.y < -10) p.y = canvas.height + 10;
        if (p.y > canvas.height + 10) p.y = -10;

        const currentAlpha = p.alpha * (0.6 + 0.4 * Math.sin(p.pulse));

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = currentAlpha;
        ctx.fill();
        ctx.globalAlpha = 1;
      });

      animId = requestAnimationFrame(draw);
    };
    draw();

    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener('resize', resize);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 0 }}
    />
  );
}

const VendorLogin = () => {
  const navigate  = useNavigate();
  const location  = useLocation();
  const [whatsapp, setWhatsapp]         = useState('');
  const [password, setPassword]         = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading]           = useState(false);
  const [error, setError]               = useState('');
  const [typed, setTyped]               = useState('');
  const [showExpiredDialog, setShowExpiredDialog] = useState(
    !!location.state?.expired
  );

  // Clear location.state agar tidak muncul lagi saat refresh
  useEffect(() => {
    if (location.state?.expired) {
      window.history.replaceState({}, '', location.pathname);
    }
  }, []);

  // Typewriter effect
  useEffect(() => {
    let idx = 0, charIdx = 0, timer;
    const tick = () => {
      const cur = TAGLINES[idx];
      if (charIdx < cur.length) {
        setTyped(cur.slice(0, charIdx + 1));
        charIdx++;
        timer = setTimeout(tick, 55);
      } else {
        timer = setTimeout(() => {
          charIdx = 0;
          idx = (idx + 1) % TAGLINES.length;
          setTyped('');
          tick();
        }, 2200);
      }
    };
    tick();
    return () => clearTimeout(timer);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!whatsapp || !password) {
      setError('Nomor WhatsApp dan password harus diisi');
      setLoading(false);
      return;
    }

    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phone: whatsapp, password }),
      });

      let data;
      try { data = await res.json(); }
      catch {
        setError('Respons server tidak valid');
        setLoading(false);
        return;
      }

      if (!res.ok) {
        if (data.detail) {
          setError(Array.isArray(data.detail)
            ? data.detail.map(e => e.msg || JSON.stringify(e)).join(', ')
            : typeof data.detail === 'string' ? data.detail : 'Login gagal');
        } else {
          setError(data.message || 'Login gagal');
        }
        setLoading(false);
        return;
      }

      localStorage.setItem('vendor_token', data.token);
      localStorage.setItem('vendor_user', JSON.stringify(data.user));
      navigate('/vendor');
    } catch {
      setError('Koneksi gagal. Silakan coba lagi.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden"
      style={{ background: '#f8f9fb' }}>

      {/* Popup Session Expired — khusus vendor */}
      {showExpiredDialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm mx-4 p-6 text-center">
            <div className="w-14 h-14 bg-amber-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#d97706" strokeWidth="2" strokeLinecap="round">
                <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><circle cx="12" cy="16" r="0.5" fill="#d97706"/>
              </svg>
            </div>
            <h3 className="text-lg font-bold text-gray-800 mb-2">Sesi Berakhir</h3>
            <p className="text-sm text-gray-500 mb-6">
              Sesi vendor Anda berakhir karena tidak aktif.<br/>Silakan login kembali untuk melanjutkan.
            </p>
            <button
              onClick={() => setShowExpiredDialog(false)}
              className="w-full py-2.5 rounded-xl bg-[#ed6f5c] text-white font-semibold hover:bg-[#d9604e] transition-colors text-sm">
              OK, Login Kembali
            </button>
          </div>
        </div>
      )}

      {/* Animated particle background */}
      <ParticleCanvas />

      {/* Frosted overlay so card reads clearly */}
      <div style={{
        position: 'absolute', inset: 0, zIndex: 1,
        background: 'rgba(248,249,251,0.55)',
        backdropFilter: 'blur(0.5px)',
        pointerEvents: 'none',
      }} />

      {/* Close X */}
      <a href="/login" aria-label="Kembali"
        className="absolute top-5 left-5 z-20 text-gray-400 hover:text-gray-700 transition-colors">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round">
          <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </a>

      {/* Card */}
      <div className="relative z-10 w-full max-w-3xl mx-4 rounded-2xl overflow-hidden flex"
        style={{
          minHeight: 460,
          boxShadow: '0 20px 60px rgba(0,0,0,0.12)',
          border: '1px solid rgba(255,255,255,0.8)',
          background: 'rgba(255,255,255,0.92)',
          backdropFilter: 'blur(18px)',
        }}>

        {/* ── LEFT — Form ── */}
        <div className="flex-1 px-10 py-10 flex flex-col justify-center">
          {/* Brand */}
          <div className="mb-7">
            <div className="flex items-center gap-2.5 mb-1.5">
              <div className="w-9 h-9 rounded-xl bg-[#ed6f5c] flex items-center justify-center flex-shrink-0">
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
                  <ellipse cx="12" cy="8" rx="4" ry="5" fill="white" opacity="0.9"/>
                  <path d="M4 20c0-4 3.6-7 8-7s8 3 8 7" fill="white" opacity="0.7"/>
                </svg>
              </div>
              <span className="font-bold text-gray-900 text-lg tracking-tight">Ruang Warga</span>
            </div>
            <p className="text-sm text-gray-500">Masuk ke panel Vendor Anda</p>
          </div>

          {/* Error */}
          {error && (
            <div className="mb-4 bg-red-50 border border-red-200 rounded-lg px-4 py-3">
              <p className="text-red-600 text-sm">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* WhatsApp */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">
                Nomor WhatsApp
              </label>
              <div className="relative">
                <MessageCircle className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={17} />
                <input
                  type="text"
                  value={whatsapp}
                  onChange={e => setWhatsapp(e.target.value)}
                  placeholder="81234567890"
                  autoComplete="username"
                  className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-200 bg-gray-50 text-gray-900 placeholder-gray-400 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/40 focus:border-[#ed6f5c]"
                />
              </div>
              <p className="mt-1 text-xs text-gray-400">Contoh: 81234567890 (tanpa +62)</p>
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={17} />
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="Masukkan password"
                  autoComplete="current-password"
                  className="w-full pl-10 pr-11 py-2.5 rounded-lg border border-gray-200 bg-gray-50 text-gray-900 placeholder-gray-400 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/40 focus:border-[#ed6f5c]"
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                  {showPassword ? <EyeOff size={17}/> : <Eye size={17}/>}
                </button>
              </div>
            </div>

            {/* Submit */}
            <button type="submit" disabled={loading}
              className="w-full py-2.5 rounded-lg bg-gray-400 hover:bg-gray-500 text-white font-semibold text-sm transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 mt-2">
              {loading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"/>
                  <span>Memproses...</span>
                </>
              ) : 'Masuk'}
            </button>
          </form>

          {/* Back link */}
          <div className="mt-6 pt-5 border-t border-gray-100 text-center">
            <a href="/login" className="text-sm text-gray-400 hover:text-gray-700 transition-colors">
              ← Kembali ke login utama
            </a>
          </div>
        </div>

        {/* ── RIGHT — Decorative ── */}
        <div className="hidden sm:flex flex-1 flex-col items-center justify-center border-l border-gray-100 px-8 text-center"
          style={{ background: '#f3f4f6' }}>
          <div className="text-5xl mb-5 select-none">🏘️</div>
          <h2 className="text-2xl font-bold text-gray-900 mb-3 leading-tight">
            Halo,<br/>Indonesia!
          </h2>
          <p className="text-gray-500 text-sm min-h-[22px]">
            {typed}<span className="animate-pulse font-light text-gray-400">|</span>
          </p>
        </div>
      </div>

      {/* Footer */}
      <p className="absolute bottom-5 left-0 right-0 text-center text-gray-400 text-xs z-10">
        Ruang Warga Vendor Management
      </p>
    </div>
  );
};

export default VendorLogin;
