import React, { useState, useEffect } from 'react'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'

// Nav landingpage3 — sama seperti landingpage2, kecuali: logo brand-mark
// ambil dari Vendor > Settings > Parameter Aplikasi (bukan huruf "R" statis),
// dan tombol "Masuk"/"Coba Gratis" + link "Harga" dihilangkan.
export default function Nav() {
  const c = useCMS('nav')
  const { logoUrl, appName } = useAppSettings()
  const [scrolled, setScrolled] = useState(false)
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 8)
    window.addEventListener('scroll', on, { passive: true })
    return () => window.removeEventListener('scroll', on)
  }, [])
  const links = (c.links || []).filter((l) => (l.label || '').toLowerCase() !== 'harga')
  return (
    <header className={'nav ' + (scrolled ? 'scrolled' : '')}>
      <div className="container nav-inner">
        <a href="#" className="brand">
          {logoUrl ? (
            <img src={logoUrl} alt={appName} className="brand-mark-img" />
          ) : (
            <div className="brand-mark">R</div>
          )}
          <div className="brand-name">
            <span>{c.brand_name}</span>
            <small>{c.brand_version}</small>
          </div>
        </a>
        <nav className="nav-links">
          {links.map((l, i) => (
            <a key={i} href={l.href}>{l.label}</a>
          ))}
        </nav>
      </div>
    </header>
  )
}
