import React, { useRef, useState } from 'react';
import { Camera, Upload, X, ZoomIn, ImageIcon } from 'lucide-react';
import { API_BASE_URL } from '../config/api';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from './ui/alert-dialog';

/**
 * PengaduanImageUploader
 * 
 * DUA mode:
 * A) readOnly=false, pengaduanId=null → "draft mode" 
 *    - Gambar disimpan lokal sebagai File objects (belum upload)
 *    - localFiles: File[] (untuk dikirim bareng form)
 *    - onFilesChange: (File[]) => void
 * 
 * B) readOnly=false, pengaduanId=string → "edit mode" (pengaduan sudah ada)
 *    - Bisa lihat existing images, tambah baru, hapus
 *    - savedImages: string[] (paths dari DB)
 *    - onSavedImagesChange: (string[]) => void
 *    - onFilesChange: (File[]) => void (file baru)
 * 
 * C) readOnly=true → tampilkan saja
 */
const PengaduanImageUploader = ({
  pengaduanId = null,
  savedImages = [],          // existing image paths dari DB
  onSavedImagesChange,       // callback saat existing dihapus
  localFiles = [],           // File[] belum diupload
  onFilesChange,             // callback saat file baru ditambah/hapus
  token,
  readOnly = false,
}) => {
  const fileRef = useRef();
  const cameraRef = useRef();
  const [lightbox, setLightbox] = useState(null);
  const [deletingIdx, setDeletingIdx] = useState(null);
  const [confirmState, setConfirmState] = useState({ open: false, path: null, idx: null });

  const serverUrl = (path) => `${API_BASE_URL}/${path}`;

  // Local file preview URLs
  const localPreviews = localFiles.map(f => ({
    url: URL.createObjectURL(f),
    name: f.name,
    isLocal: true,
  }));

  const serverPreviews = savedImages.map(path => ({
    url: serverUrl(path),
    path,
    isLocal: false,
  }));

  const allPreviews = [...serverPreviews, ...localPreviews];

  const handleAddFiles = (newFiles) => {
    const valid = Array.from(newFiles).filter(f => {
      if (f.size > 10 * 1024 * 1024) {
        alert(`File "${f.name}" terlalu besar (max 10MB)`);
        return false;
      }
      if (!f.type.startsWith('image/')) {
        alert(`File "${f.name}" bukan gambar`);
        return false;
      }
      return true;
    });
    if (valid.length) onFilesChange?.([...localFiles, ...valid]);
  };

  const handleRemoveLocal = (idx) => {
    const updated = localFiles.filter((_, i) => i !== idx);
    onFilesChange?.(updated);
  };

  const handleRemoveSaved = async (path, idx) => {
    setConfirmState({ open: true, path, idx });
  };

  const handleConfirmDelete = async () => {
    const { path, idx } = confirmState;
    setConfirmState({ open: false, path: null, idx: null });
    if (pengaduanId && token) {
      setDeletingIdx(idx);
      try {
        const filename = path.split('/').pop();
        await fetch(
          `${API_BASE_URL}/api/pengaduan/${pengaduanId}/delete-image?filename=${filename}`,
          { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } }
        );
      } catch (e) { console.error(e); }
      setDeletingIdx(null);
    }
    onSavedImagesChange?.(savedImages.filter(p => p !== path));
  };

  const totalCount = allPreviews.length;

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">
          Foto Pendukung
          {totalCount > 0 && (
            <span className="ml-2 text-xs bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded-full">
              {totalCount} foto
            </span>
          )}
        </label>
        {!readOnly && (
          <span className="text-xs text-gray-400">maks. 10MB per foto</span>
        )}
      </div>

      {/* Thumbnail Grid */}
      {allPreviews.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {serverPreviews.map((item, i) => (
            <div key={`saved-${i}`}
              className="relative group w-20 h-20 rounded-lg overflow-hidden border border-gray-200 dark:border-gray-700 bg-gray-50 flex-shrink-0"
            >
              <img src={item.url} alt={`foto-${i+1}`}
                className="w-full h-full object-cover"
                onError={e => { e.target.src = ''; e.target.parentElement.classList.add('border-red-300'); }}
              />
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1">
                <button type="button" onClick={() => setLightbox(item.url)}
                  className="p-1 bg-white/80 rounded-full hover:bg-white">
                  <ZoomIn className="w-3.5 h-3.5 text-gray-800" />
                </button>
                {!readOnly && (
                  <button type="button"
                    onClick={() => handleRemoveSaved(item.path, i)}
                    disabled={deletingIdx === i}
                    className="p-1 bg-white/80 rounded-full hover:bg-red-100 disabled:opacity-50">
                    <X className="w-3.5 h-3.5 text-red-600" />
                  </button>
                )}
              </div>
              {/* Server badge */}
              <div className="absolute bottom-0 left-0 right-0 bg-black/40 text-white text-[9px] text-center py-0.5">
                tersimpan
              </div>
            </div>
          ))}

          {localPreviews.map((item, i) => (
            <div key={`local-${i}`}
              className="relative group w-20 h-20 rounded-lg overflow-hidden border-2 border-dashed border-blue-400 bg-blue-50 flex-shrink-0"
            >
              <img src={item.url} alt={item.name}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1">
                <button type="button" onClick={() => setLightbox(item.url)}
                  className="p-1 bg-white/80 rounded-full hover:bg-white">
                  <ZoomIn className="w-3.5 h-3.5 text-gray-800" />
                </button>
                {!readOnly && (
                  <button type="button" onClick={() => handleRemoveLocal(i)}
                    className="p-1 bg-white/80 rounded-full hover:bg-red-100">
                    <X className="w-3.5 h-3.5 text-red-600" />
                  </button>
                )}
              </div>
              {/* Local badge */}
              <div className="absolute bottom-0 left-0 right-0 bg-blue-500/80 text-white text-[9px] text-center py-0.5">
                belum simpan
              </div>
            </div>
          ))}

          {/* Add more button */}
          {!readOnly && (
            <button type="button" onClick={() => fileRef.current?.click()}
              className="w-20 h-20 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors flex flex-col items-center justify-center gap-1 flex-shrink-0">
              <Upload className="w-5 h-5 text-gray-400" />
              <span className="text-[10px] text-gray-400">Tambah</span>
            </button>
          )}
        </div>
      )}

      {/* Upload buttons (shown when no images yet) */}
      {!readOnly && allPreviews.length === 0 && (
        <div className="border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-lg p-4">
          <div className="flex flex-col items-center gap-3 text-center">
            <ImageIcon className="w-8 h-8 text-gray-300" />
            <p className="text-xs text-gray-400">Tambahkan foto pendukung pengaduan</p>
            <div className="flex gap-2 flex-wrap justify-center">
              {/* Camera button */}
              <button type="button" onClick={() => cameraRef.current?.click()}
                className="flex items-center gap-2 px-3 py-2 text-sm bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors shadow-sm">
                <Camera className="w-4 h-4 text-gray-500" />
                <span className="text-gray-600 dark:text-gray-400">Kamera</span>
              </button>
              {/* File picker */}
              <button type="button" onClick={() => fileRef.current?.click()}
                className="flex items-center gap-2 px-3 py-2 text-sm bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors shadow-sm">
                <Upload className="w-4 h-4 text-gray-500" />
                <span className="text-gray-600 dark:text-gray-400">Pilih File</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Compact upload buttons when images exist */}
      {!readOnly && allPreviews.length > 0 && (
        <div className="flex gap-2">
          <button type="button" onClick={() => cameraRef.current?.click()}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors">
            <Camera className="w-3.5 h-3.5 text-gray-500" />
            <span className="text-gray-600 dark:text-gray-400">Kamera</span>
          </button>
        </div>
      )}

      {/* Hidden inputs */}
      <input ref={cameraRef} type="file" accept="image/*" capture="environment"
        multiple className="hidden"
        onChange={e => e.target.files?.length && handleAddFiles(e.target.files)} />
      <input ref={fileRef} type="file" accept="image/*"
        multiple className="hidden"
        onChange={e => e.target.files?.length && handleAddFiles(e.target.files)} />

      {/* Lightbox */}
      {lightbox && (
        <div className="fixed inset-0 z-[9999] bg-black/90 flex items-center justify-center"
          onClick={() => setLightbox(null)}>
          <button className="absolute top-4 right-4 p-2 bg-white/20 rounded-full hover:bg-white/40 z-10"
            onClick={() => setLightbox(null)}>
            <X className="w-6 h-6 text-white" />
          </button>
          <img src={lightbox} alt="preview"
            className="max-w-[92vw] max-h-[92vh] rounded-xl object-contain shadow-2xl"
            onClick={e => e.stopPropagation()} />
        </div>
      )}
      {/* Confirm delete dialog */}
      <AlertDialog open={confirmState.open} onOpenChange={open => !open && setConfirmState(p => ({ ...p, open: false }))}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Foto</AlertDialogTitle>
            <AlertDialogDescription>
              Foto ini akan dihapus permanen. Tindakan ini tidak dapat dibatalkan.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmDelete}
              className="bg-red-600 hover:bg-red-700 text-white">
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default PengaduanImageUploader;
