import { useEffect, useState } from "react";

import { API_BASE_URL } from '@/config/api';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { Loader2 } from "lucide-react";

export default function PelunasanKasbonPage() {
  const [kasbon, setKasbon] = useState([]);
  const [pegawai, setPegawai] = useState([]);
  const { token, user, logout } = useAuth();
  const { canCreate } = useRolePermissions(user?.role, token);

  // FORM STATE
  const [openForm, setOpenForm] = useState(false);
  const [formData, setFormData] = useState({
    kasbon_id: "",
    nominal: "",
    metode: "Tunai",
    keterangan: "",
  });
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  // PAGINATION
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);

  // LOAD DATA
  const loadKasbon = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        logout();
        return;
      }

      const data = await res.json();
      // Filter only belum lunas
      setKasbon(data.filter((k) => k.status === "Belum Lunas"));
    } catch (err) {
      console.error("Gagal load kasbon", err);
      toast.error("Gagal memuat data kasbon");
    }
  };

  const loadPegawai = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/karyawan`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.ok) {
        const data = await res.json();
        // Filter hanya karyawan yang aktif
        const activePegawai = data.filter((k) => k.status === "active");
        setPegawai(activePegawai);
      }
    } catch (err) {
      console.error("Gagal load pegawai", err);
      toast.error("Gagal memuat data pegawai");
    }
  };

  useEffect(() => {
    loadKasbon();
    loadPegawai();
  }, []);

  // HANDLE PELUNASAN
  const handlePelunasan = async () => {
    if (!formData.kasbon_id || !formData.nominal) {
      toast.error("Kasbon dan Nominal harus diisi");
      return;
    }

    const selectedKasbon = kasbon.find((k) => k.id === formData.kasbon_id);
    if (!selectedKasbon) {
      toast.error("Kasbon tidak ditemukan");
      return;
    }

    if (parseFloat(formData.nominal) > selectedKasbon.sisa) {
      toast.error(`Nominal melebihi sisa kasbon (${formatRupiah(selectedKasbon.sisa)})`);
      return;
    }

    setLoading(true);

    try {
      const res = await fetch(`${API_BASE_URL}/api/kasbon/pelunasan/process`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          kasbon_id: formData.kasbon_id,
          nominal: parseFloat(formData.nominal),
          metode: formData.metode,
          keterangan: formData.keterangan,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        setResult(data);
        toast.success("Pelunasan berhasil diproses");
        loadKasbon();
        resetForm();
      } else {
        const error = await res.json();
        toast.error(error.detail || "Gagal memproses pelunasan");
      }
    } catch (err) {
      console.error("Error:", err);
      toast.error("Terjadi kesalahan saat memproses pelunasan");
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      kasbon_id: "",
      nominal: "",
      metode: "Tunai",
      keterangan: "",
    });
    setResult(null);
  };

  const formatRupiah = (val) => {
    return new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      minimumFractionDigits: 0,
    }).format(val);
  };

  const getPegawaiName = (pegawaiId) => {
    return pegawai.find((p) => p.id === pegawaiId)?.nama_lengkap || "-";
  };

  const handleNominalChange = (e) => {
    // Remove all non-digit characters
    const value = e.target.value.replace(/\D/g, '');
    setFormData({ ...formData, nominal: value });
  };

  const displayNominal = () => {
    if (!formData.nominal) return '';
    return new Intl.NumberFormat("id-ID").format(formData.nominal);
  };

  const selectedKasbon = kasbon.find((k) => k.id === formData.kasbon_id);
  const remainingAfterPayment = selectedKasbon
    ? selectedKasbon.sisa - parseFloat(formData.nominal || 0)
    : 0;

  // PAGINATION
  const totalPages = Math.ceil(kasbon.length / perPage);
  const paginatedData = kasbon.slice((page - 1) * perPage, page * perPage);

  return (
    <div className="p-6 space-y-6">
      {/* HEADER */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold dark:text-gray-100">Pelunasan Kasbon</h1>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Proses pelunasan kasbon pegawai
          </p>
        </div>
        {canCreate("kasbon") && (
          <Button
            onClick={() => setOpenForm(true)}
            className="bg-green-500 hover:bg-green-600 text-white"
          >
            + Proses Pelunasan
          </Button>
        )}
      </div>

      {/* TABLE - KASBON BELUM LUNAS */}
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-900 rounded-lg border dark:border-gray-700">
        <div className="p-4 border-b dark:border-gray-700">
          <h2 className="font-semibold">Kasbon Belum Lunas</h2>
        </div>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Nama Pegawai</TableHead>
              <TableHead className="text-right">Nominal</TableHead>
              <TableHead className="text-right">Sisa</TableHead>
              <TableHead>Tanggal</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {paginatedData.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} className="text-center text-gray-500">
                  Tidak ada kasbon belum lunas
                </TableCell>
              </TableRow>
            ) : (
              paginatedData.map((item) => (
                <TableRow key={item.id}>
                  <TableCell>
                    <p className="font-medium">{getPegawaiName(item.pegawai_id)}</p>
                    {item.keterangan && (
                      <p className="text-xs text-gray-500">{item.keterangan}</p>
                    )}
                  </TableCell>
                  <TableCell className="text-right font-medium">
                    {formatRupiah(item.nominal)}
                  </TableCell>
                  <TableCell className="text-right font-medium text-orange-600 dark:text-orange-400">
                    {formatRupiah(item.sisa)}
                  </TableCell>
                  <TableCell className="text-sm">
                    {item.tanggal ? new Date(item.tanggal).toLocaleDateString("id-ID") : "-"}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        {/* PAGINATION */}
        {totalPages > 1 && (
          <div className="p-4 border-t dark:border-gray-700 flex justify-between items-center">
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Halaman {page} dari {totalPages} ({kasbon.length} total)
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 1}
                onClick={() => setPage(page - 1)}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page === totalPages}
                onClick={() => setPage(page + 1)}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>

      {/* FORM DIALOG */}
      <Dialog open={openForm} onOpenChange={setOpenForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Proses Pelunasan Kasbon</DialogTitle>
          </DialogHeader>

          {!result ? (
            <div className="space-y-4">
              <div>
                <Label htmlFor="kasbon">Pilih Kasbon</Label>
                <Select
                  value={formData.kasbon_id}
                  onValueChange={(value) => setFormData({ ...formData, kasbon_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Pilih kasbon" />
                  </SelectTrigger>
                  <SelectContent>
                    {kasbon.map((k) => (
                      <SelectItem key={k.id} value={k.id}>
                        {getPegawaiName(k.pegawai_id)} - {formatRupiah(k.sisa)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {selectedKasbon && (
                <div className="p-3 bg-blue-50 dark:bg-blue-900/20 rounded border border-blue-200 dark:border-blue-800">
                  <p className="text-sm">
                    <span className="font-semibold">Sisa Kasbon:</span> {formatRupiah(selectedKasbon.sisa)}
                  </p>
                </div>
              )}

              <div>
                <Label htmlFor="nominal">Nominal Pelunasan (Rp)</Label>
                <Input
                  id="nominal"
                  type="text"
                  value={displayNominal()}
                  onChange={handleNominalChange}
                  placeholder="100000"
                />
              </div>

              {remainingAfterPayment >= 0 && (
                <div className="p-3 bg-green-50 dark:bg-green-900/20 rounded border border-green-200 dark:border-green-800">
                  <p className="text-sm">
                    <span className="font-semibold">Sisa Setelah Bayar:</span>{" "}
                    {formatRupiah(remainingAfterPayment)}
                  </p>
                </div>
              )}

              <div>
                <Label>Metode Pelunasan</Label>
                <RadioGroup value={formData.metode} onValueChange={(value) => setFormData({ ...formData, metode: value })}>
                  <div className="flex items-center space-x-2 mt-2">
                    <RadioGroupItem value="Tunai" id="tunai" />
                    <Label htmlFor="tunai" className="font-normal cursor-pointer">
                      Tunai (Masuk ke Kas)
                    </Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="Potong Gaji" id="potong" />
                    <Label htmlFor="potong" className="font-normal cursor-pointer">
                      Potong Gaji (Tidak Masuk Kas)
                    </Label>
                  </div>
                </RadioGroup>
              </div>

              <div>
                <Label htmlFor="keterangan">Keterangan (Opsional)</Label>
                <Input
                  id="keterangan"
                  value={formData.keterangan}
                  onChange={(e) => setFormData({ ...formData, keterangan: e.target.value })}
                  placeholder="Catatan pelunasan"
                />
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="p-4 bg-green-50 dark:bg-green-900/20 rounded border border-green-200 dark:border-green-800">
                <p className="font-semibold text-green-800 dark:text-green-300">
                  ✓ Pelunasan Berhasil Diproses
                </p>
                <div className="mt-3 space-y-2 text-sm">
                  <p>
                    <span className="font-semibold">Nominal:</span> {formatRupiah(result.sisa_baru ? selectedKasbon.sisa - parseFloat(formData.nominal) : result.sisa_baru)}
                  </p>
                  <p>
                    <span className="font-semibold">Sisa Baru:</span> {formatRupiah(result.sisa_baru)}
                  </p>
                  <p>
                    <span className="font-semibold">Status:</span>{" "}
                    <span className={`px-2 py-1 rounded text-xs font-semibold ${
                      result.status === "Lunas"
                        ? "bg-green-100 text-green-700"
                        : "bg-yellow-100 text-yellow-700"
                    }`}>
                      {result.status}
                    </span>
                  </p>
                </div>
              </div>
            </div>
          )}

          <DialogFooter>
            {result ? (
              <Button
                onClick={() => setOpenForm(false)}
                className="bg-gray-500 hover:bg-gray-600"
              >
                Tutup
              </Button>
            ) : (
              <>
                <Button variant="outline" onClick={() => setOpenForm(false)}>
                  Batal
                </Button>
                <Button onClick={handlePelunasan} disabled={loading}>
                  {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  Proses Pelunasan
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
