/**
 * Check if a role can perform an action on a menu
 * @param {string} role - User role (admin, warga, karyawan)
 * @param {string} menuId - Menu identifier
 * @param {string} action - Action (read, create, update, delete)
 * @returns {boolean} True if allowed
 */
export const hasPermission = (role, menuId, action = 'read') => {
  const rolePermissions = PERMISSIONS_MATRIX[role];
  // Role yang tidak ada di matrix statis (misal pengurus_rw, pengurus_kelurahan)
  // dikonfigurasi oleh vendor via DB — izinkan akses, sidebar yg menyaring
  if (!rolePermissions) return true;

  const menuPermissions = rolePermissions[menuId];
  if (!menuPermissions) return false;

  return menuPermissions[action] === true;
};

/**
 * Get all permissions for a role on a menu
 * @param {string} role - User role
 * @param {string} menuId - Menu identifier
 * @returns {Object} CRUD permissions object
 */
export const getMenuPermissions = (role, menuId) => {
  return PERMISSIONS_MATRIX[role]?.[menuId] || {
    read: false,
    create: false,
    update: false,
    delete: false,
  };
};

/**
 * Check if user can read/access a menu
 */
export const canReadMenu = (role, menuId) => hasPermission(role, menuId, 'read');

/**
 * Check if user can create in a menu
 */
export const canCreateInMenu = (role, menuId) => hasPermission(role, menuId, 'create');

/**
 * Check if user can update in a menu
 */
export const canUpdateInMenu = (role, menuId) => hasPermission(role, menuId, 'update');

/**
 * Check if user can delete in a menu
 */
export const canDeleteInMenu = (role, menuId) => hasPermission(role, menuId, 'delete');

/**
 * Get accessible menus for a role
 * @param {string} role - User role
 * @returns {Array} List of accessible menu IDs
 */
export const getAccessibleMenus = (role) => {
  const rolePermissions = PERMISSIONS_MATRIX[role];
  if (!rolePermissions) return [];

  return Object.entries(rolePermissions)
    .filter(([_, perms]) => perms.read === true)
    .map(([menuId, _]) => menuId);
};

/**
 * Initialize permissions for new user/role
 */
export const initializeMenuPermissions = () => {
  const perms = {};
  MENU_ITEMS.forEach((item) => {
    perms[item.id] = {
      read: false,
      create: false,
      update: false,
      delete: false,
    };
  });
  return perms;
};
