import React from 'react';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Smartphone, Lock, AlertCircle, Headset, ArrowRight } from 'lucide-react';
import { API_BASE_URL } from '../../config/api';

// Tema login "Elegant Card" — satu kartu kaca (glass) melayang di tengah
// layar di atas latar gradien lembut dengan aksen blur berwarna, tanpa
// pembagian panel kiri/kanan sama sekali. Form login ditaruh di dalam
// sub-panel putih buram (frosted) di dalam kartu kaca supaya tetap kontras
// dan mudah dibaca di atas latar gelap.
export default function LoginLayoutElegant({
  branding, logo, appTitle, appDescription, vendorAppName, primaryColorStyle,
  phone, setPhone, password, setPassword, error, isLoading, handleSubmit, navigate,
  SOCIAL_ICONS,
}) {
  return (
    <div
      className="relative min-h-screen flex items-center justify-center overflow-hidden bg-[color-mix(in_srgb,var(--rw-primary)_25%,black)] px-4 py-10 sm:py-16"
      style={primaryColorStyle}
    >
      {/* Latar gradien + gambar (opsional) */}
      <div className="absolute inset-0 bg-gradient-to-br from-[color-mix(in_srgb,var(--rw-primary)_55%,black)] via-[color-mix(in_srgb,var(--rw-primary)_30%,black)] to-black" />
      {branding?.login_bg_url && (
        <div
          className="absolute inset-0 bg-cover bg-center opacity-30"
          style={{ backgroundImage: `url(${API_BASE_URL}${branding.login_bg_url})` }}
        />
      )}

      {/* Aksen blur dekoratif */}
      <div className="absolute -top-24 -left-24 w-80 h-80 rounded-full bg-[var(--rw-primary)] opacity-30 blur-3xl" aria-hidden="true" />
      <div className="absolute -bottom-32 -right-16 w-96 h-96 rounded-full bg-[color-mix(in_srgb,var(--rw-primary)_60%,white)] opacity-20 blur-3xl" aria-hidden="true" />
      <div className="absolute top-1/3 right-1/4 w-40 h-40 rounded-full bg-white opacity-10 blur-2xl" aria-hidden="true" />

      {vendorAppName && (
        <div className="absolute top-5 left-1/2 -translate-x-1/2 z-10 text-[10px] sm:text-xs font-medium tracking-[0.2em] uppercase text-white/50">
          {vendorAppName}
        </div>
      )}

      {/* Kartu kaca */}
      <div className="relative z-10 w-full max-w-md">
        <div className="rounded-[28px] border border-white/20 bg-white/10 backdrop-blur-xl shadow-2xl p-6 sm:p-10">
          <div className="flex flex-col items-center text-center text-white">
            <img src={logo} alt={appTitle} className="w-16 h-16 sm:w-20 sm:h-20 object-contain rounded-2xl bg-white/90 p-2 shadow-lg mb-4" />
            <h1 className="text-xl sm:text-2xl font-bold">{appTitle}</h1>
            <p className="text-xs sm:text-sm uppercase tracking-widest text-white/70 mt-1">Manajemen Pengurus</p>
            {branding?.login_caption && (
              <p className="mt-2 text-xs sm:text-sm text-white/60 max-w-xs">{branding.login_caption}</p>
            )}
          </div>

          {/* Sub-panel putih buram — form tetap kontras di atas kartu kaca */}
          <div className="mt-7 rounded-2xl bg-white/95 dark:bg-gray-900/95 p-5 sm:p-7 shadow-inner">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="phone" className="text-gray-700 dark:text-gray-300 text-sm">No WhatsApp</Label>
                <div className="relative">
                  <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    id="phone" type="tel" placeholder="08xxxxxxxxxx"
                    value={phone} onChange={(e) => setPhone(e.target.value)}
                    className="pl-11 h-11 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 border-[var(--rw-border)] dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-[var(--rw-primary)] focus:border-transparent"
                    disabled={isLoading} autoComplete="tel"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="password" className="text-gray-700 dark:text-gray-300 text-sm">Password</Label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    id="password" type="password" placeholder="Masukkan password"
                    value={password} onChange={(e) => setPassword(e.target.value)}
                    className="pl-11 h-11 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 border-[var(--rw-border)] dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-[var(--rw-primary)] focus:border-transparent"
                    disabled={isLoading} autoComplete="current-password"
                  />
                </div>
              </div>

              {error && (
                <div className="flex items-center gap-2 p-2.5 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                  <AlertCircle className="h-4 w-4 flex-shrink-0" />
                  <p className="text-xs">{error}</p>
                </div>
              )}

              <Button
                type="submit"
                className="w-full h-11 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white font-semibold rounded-xl shadow-lg transition-all hover:scale-[1.02]"
                disabled={isLoading}
              >
                {isLoading ? 'Memproses...' : 'Login'}
              </Button>

              <div className="flex items-center justify-center gap-3 pt-1">
                <span className="text-xs text-gray-500 dark:text-gray-400">Belum punya akun?</span>
                <Button
                  type="button" variant="ghost"
                  className="text-[var(--rw-primary)] font-semibold hover:text-[color-mix(in_srgb,var(--rw-primary)_70%,black)] hover:bg-[color-mix(in_srgb,var(--rw-primary)_15%,white)] dark:hover:bg-[color-mix(in_srgb,var(--rw-primary)_20%,transparent)] px-3 text-xs h-8"
                  onClick={() => navigate('/register')} disabled={isLoading}
                >
                  Daftar Warga
                </Button>
              </div>
            </form>
          </div>

          {branding?.support_whatsapp && (
            <div className="flex justify-center pt-5">
              <a
                href={`https://wa.me/${branding.support_whatsapp}`} target="_blank" rel="noopener noreferrer"
                className="flex items-center gap-3 bg-white/95 dark:bg-gray-900/95 border border-white/30 rounded-2xl shadow-md px-4 py-2.5 hover:shadow-lg transition-shadow max-w-full"
              >
                <div className="w-8 h-8 rounded-full bg-[color-mix(in_srgb,var(--rw-primary)_15%,white)] dark:bg-[color-mix(in_srgb,var(--rw-primary)_25%,black)] flex items-center justify-center flex-shrink-0">
                  <Headset size={14} className="text-[var(--rw-primary)]" />
                </div>
                <div className="min-w-0 text-left">
                  <p className="text-[11px] text-gray-500 dark:text-gray-400">Butuh bantuan?</p>
                  <p className="text-xs font-semibold text-gray-800 dark:text-white truncate">Hubungi Pengurus {appTitle}</p>
                </div>
                <ArrowRight size={14} className="text-gray-400 flex-shrink-0" />
              </a>
            </div>
          )}

          {branding?.social && Object.values(branding.social).some(Boolean) && (
            <div className="flex items-center justify-center gap-2.5 pt-5">
              {SOCIAL_ICONS.filter(({ key }) => branding.social[key]).map(({ key, label, Icon }) => (
                <a
                  key={key} href={branding.social[key]} target="_blank" rel="noopener noreferrer" title={label}
                  className="w-8 h-8 rounded-full flex items-center justify-center border border-white/30 text-white/70 hover:text-white hover:border-white transition-colors"
                >
                  <Icon size={14} />
                </a>
              ))}
            </div>
          )}
        </div>

        <p className="mt-5 text-center text-[11px] text-white/40">{appDescription}</p>
      </div>
    </div>
  );
}
