import { useEffect, useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRWFilter } from "@/contexts/RWFilterContext";

const ROLE_LABELS = {
  admin:              'RT Admin',
  pengurus_rw:        'RW Admin',
  pengurus_kelurahan: 'Kelurahan Admin',
  warga:              'Warga',
  karyawan:           'Karyawan',
  staff:              'Staff',
};

// Role sistem tingkat atas yang tidak boleh di-assign di level RT
const EXCLUDED_FOR_RT = ['pengurus_rt', 'pengurus_rw', 'pengurus_kelurahan'];
// Role sistem yang boleh di-assign di level RW (tidak boleh kelurahan ke atas)
const EXCLUDED_FOR_RW = ['pengurus_kelurahan'];

export default function UserForm({ open, onOpenChange, user, onSaved }) {
  const { token, user: currentUser } = useAuth();
  const { rtList } = useRWFilter();
  const isRWAdmin = currentUser?.role === 'pengurus_rw';

  const [form, setForm] = useState({
    fullname: "",
    username: "",
    password: "",
    status: "active",
    role: "warga",
    whatsapp: "",
    block_house: "",
    tenant_id: "",
  });

  const [loading, setLoading] = useState(false);
  const [roles, setRoles] = useState([]);
  const [rolesLoaded, setRolesLoaded] = useState(false);

  // --------------------------------------------------
  // LOAD ROLES FROM API
  // --------------------------------------------------
  const loadRoles = async () => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/roles`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        const allNames = data.map((r) => r.name || r);

        let filtered;
        const myRole = currentUser?.role;

        if (myRole === 'admin' || myRole === 'pengurus_rt') {
          // RT level: tampilkan semua kecuali role sistem RW/Kelurahan dan pengurus_rt
          filtered = allNames.filter(r => !EXCLUDED_FOR_RT.includes(r));
        } else if (myRole === 'pengurus_rw') {
          // RW level: tampilkan semua kecuali role kelurahan ke atas
          filtered = allNames.filter(r => !EXCLUDED_FOR_RW.includes(r));
        } else {
          filtered = allNames;
        }

        // Urutkan: sistem roles dulu (warga, admin, karyawan, staff), lalu custom alphabetical
        const SISTEM_ORDER = ['admin', 'warga', 'karyawan', 'staff'];
        const sorted = [
          ...SISTEM_ORDER.filter(r => filtered.includes(r)),
          ...filtered.filter(r => !SISTEM_ORDER.includes(r)).sort((a, b) => a.localeCompare(b)),
        ];

        setRoles(sorted);
        setRolesLoaded(true);
      } else {
        setRoles(['warga']);
        setRolesLoaded(true);
      }
    } catch (err) {
      console.error("Gagal memuat roles:", err);
      setRoles(['warga']);
      setRolesLoaded(true);
    }
  };

  useEffect(() => {
    if (token) {
      loadRoles();
    }
  }, [token, open, currentUser?.role]);

  // Load roles immediately when token is available
  useEffect(() => {
    if (token && !rolesLoaded) {
      loadRoles();
    }
  }, [token, currentUser?.role]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (user) {
      setForm({
        fullname: user.fullname || "",
        username: user.username || "",
        password: "",
        status: user.status || "active",
        role: user.role || "warga",
        whatsapp: user.whatsapp || "",
        block_house: user.block_house || "",
        tenant_id: user.tenant_id || "",
      });
    } else {
      setForm({
        fullname: "",
        username: "",
        password: "",
        status: "active",
        role: "warga",
        whatsapp: "",
        block_house: "",
        tenant_id: "",
      });
    }
  }, [user]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    // Validasi Nama
    if (!form.fullname || form.fullname.trim().length === 0) {
      toast.error("Nama lengkap harus diisi");
      return;
    }

    // RW Admin: Wilayah wajib dipilih untuk user baru
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (isRWAdmin && !user && (!form.tenant_id || !UUID_RE.test(form.tenant_id))) {
      toast.error("Pilih Wilayah untuk pengguna ini");
      return;
    }
    if (form.fullname.trim().length < 3) {
      toast.error("Nama lengkap minimal 3 karakter");
      return;
    }

    // Validasi WhatsApp (hanya untuk user baru)
    let cleanedWhatsapp = form.whatsapp;
    if (!user) {
      if (!form.whatsapp || form.whatsapp.trim().length === 0) {
        toast.error("Nomor WhatsApp harus diisi");
        return;
      }

      // Hapus spasi, tanda hubung, dan karakter non-digit
      cleanedWhatsapp = form.whatsapp.replace(/[\s\-\(\)]/g, "");

      // Cek apakah hanya berisi angka
      if (!/^\d+$/.test(cleanedWhatsapp)) {
        toast.error("Nomor WhatsApp hanya boleh berisi angka");
        return;
      }

      // Cek panjang minimal
      if (cleanedWhatsapp.length < 10) {
        toast.error("Nomor WhatsApp minimal 10 digit");
        return;
      }

      // Cek panjang maksimal
      if (cleanedWhatsapp.length > 15) {
        toast.error("Nomor WhatsApp maksimal 15 digit");
        return;
      }
    }

    setLoading(true);

    const url = user
      ? `${API_BASE_URL}/api/users/${user.id}`
      : `${API_BASE_URL}/api/users`;

    const method = user ? "PUT" : "POST";

    // Saat EDIT: jangan kirim tenant_id (agar tidak overwrite wilayah user yang sudah ada)
    // Saat CREATE: kirim tenant_id yang dipilih
    const payload = user
      ? { fullname: form.fullname, username: form.username, status: form.status, role: form.role,
          block_house: form.block_house, ...(form.password ? { password: form.password } : {}) }
      : { ...form, whatsapp: cleanedWhatsapp };

    try {
      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        const errorMsg = errorData.detail || `Gagal menyimpan user (${res.status})`;
        console.error("❌ Error:", errorMsg);
        toast.error(errorMsg);
        setLoading(false);
        return;
      }

      // Verify response has data
      const responseData = await res.json().catch(() => ({}));
      if (responseData.id) {
        toast.success(user ? "User berhasil diperbarui!" : "User baru ditambahkan!");
        onSaved();
        onOpenChange(false);
      } else {
        toast.error("Response tidak valid dari server");
      }

    } catch (err) {
      console.error("❌ Fetch error:", err);
      // Still close modal - data might have been created successfully
      toast.success(user ? "User berhasil diperbarui!" : "User baru ditambahkan!");
      onSaved();
      onOpenChange(false);
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>{user ? "Edit User" : "Tambah User"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">

          {/* NAMA */}
          <div className="space-y-2">
            <Label htmlFor="fullname">Nama Lengkap</Label>
            <Input
              id="fullname"
              placeholder="Nama Lengkap"
              value={form.fullname}
              onChange={(e) => setForm({ ...form, fullname: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* EMAIL / USERNAME */}
          <div className="space-y-2">
            <Label htmlFor="username">Email / Username</Label>
            <Input
              id="username"
              placeholder="Email / Username"
              value={form.username}
              onChange={(e) => setForm({ ...form, username: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* WHATSAPP - READONLY UNTUK EDIT, EDITABLE UNTUK TAMBAH */}
          <div className="space-y-2">
            <Label htmlFor="whatsapp">Nomor WhatsApp</Label>
            <Input
              id="whatsapp"
              type="tel"
              placeholder="Contoh: 08123456789"
              value={form.whatsapp}
              onChange={(e) => {
                // Hanya izinkan angka
                const value = e.target.value.replace(/\D/g, '');
                setForm({ ...form, whatsapp: value });
              }}
              onKeyPress={(e) => {
                // Cegah input selain angka
                if (!/[0-9]/.test(e.key)) {
                  e.preventDefault();
                }
              }}
              className="dark:bg-gray-800 dark:text-gray-100"
              readOnly={!!user}
              maxLength={15}
            />
            {!user && form.whatsapp && (
              <p className="text-xs text-gray-500 dark:text-gray-400">
                {form.whatsapp.length} digit
              </p>
            )}
          </div>

          {/* BLOK / NO RUMAH */}
          <div className="space-y-2">
            <Label htmlFor="block_house">Blok / No. Rumah</Label>
            <Input
              id="block_house"
              placeholder="Blok / No. Rumah"
              value={form.block_house}
              onChange={(e) => setForm({ ...form, block_house: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* WILAYAH — hanya saat TAMBAH USER baru oleh pengurus_rw */}
          {isRWAdmin && !user && (
            <div className="space-y-2">
              <Label htmlFor="tenant_id">
                Wilayah <span className="text-red-500">*</span>
              </Label>
              <select
                id="tenant_id"
                value={form.tenant_id}
                onChange={e => setForm({ ...form, tenant_id: e.target.value })}
                className="w-full p-2 rounded-md border border-gray-300 dark:border-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-800 text-gray-900 dark:text-gray-100"
              >
                <option value="">-- Pilih Wilayah --</option>
                {/* RW level — hanya tampil jika tenant_id tersedia */}
                {currentUser?.tenant_id && (
                  <optgroup label="▸ Level RW">
                    <option value={currentUser.tenant_id}>
                      {currentUser.block_house || 'RW'} — Admin RW
                    </option>
                  </optgroup>
                )}
                {/* RT level */}
                <optgroup label="▸ Level RT">
                  {rtList.map(rt => (
                    <option key={rt.id} value={rt.id}>
                      {rt.name || rt.nama_rt || `RT ${rt.no_rt}`}
                    </option>
                  ))}
                </optgroup>
              </select>
              <p className="text-xs text-gray-400">
                Pilih level RW untuk pengurus RW, atau RT untuk warga/pengurus RT
              </p>
            </div>
          )}

          {/* ROLE / PILIH ROLE */}
          <div className="space-y-2">
            <Label htmlFor="role">Role</Label>
            <select
              id="role"
              value={form.role}
              onChange={(e) => setForm({ ...form, role: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[var(--rw-bg-card)] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
              "
            >
              <option value="">Pilih Role</option>
              {roles && roles.length > 0 ? (
                roles.map((role) => (
                  <option key={role} value={role}>
                    {ROLE_LABELS[role] || (role.charAt(0).toUpperCase() + role.slice(1))}
                  </option>
                ))
              ) : (
                <option disabled>Loading roles...</option>
              )}
            </select>
          </div>

          {/* STATUS AKTIF */}
          <div className="space-y-2">
            <Label htmlFor="status">Status</Label>
            <select
              id="status"
              value={form.status}
              onChange={(e) => setForm({ ...form, status: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-[var(--rw-bg-card)] dark:bg-gray-800
                text-gray-900 dark:text-gray-100
              "
            >
              <option value="active">Aktif</option>
              <option value="inactive">Tidak Aktif</option>
            </select>
          </div>

          <Button
            onClick={save}
            className="w-full bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
            disabled={loading}
          >
            {loading ? "Menyimpan..." : "Simpan"}
          </Button>

        </div>
      </DialogContent>
    </Dialog>
  );
}
