import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../../contexts/AuthContext';
import { API_BASE_URL } from '../../config/api';
import { Building2, Plus, Pencil, Trash2, RefreshCw, MapPin, User } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

const ProfileRW = () => {
  const { token } = useAuth();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState(null);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    nomor_rw: '', nama_rw: '', ketua_rw: '',
    alamat_sekretariat: '', aktif: true
  });

  useEffect(() => { fetchData(); }, [token]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      const res = await axios.get(`${API_BASE_URL}/api/rw/profile`, { headers });
      setData(res.data?.data || []);
      setError(null);
    } catch (err) {
      setError(err.response?.data?.detail || err.message);
    } finally {
      setLoading(false);
    }
  };

  const openAdd = () => {
    setEditItem(null);
    setForm({ nomor_rw: '', nama_rw: '', ketua_rw: '', alamat_sekretariat: '', aktif: true });
    setShowForm(true);
  };

  const openEdit = (item) => {
    setEditItem(item);
    setForm({
      nomor_rw: item.nomor_rw, nama_rw: item.nama_rw,
      ketua_rw: item.ketua_rw || '', alamat_sekretariat: item.alamat_sekretariat || '',
      aktif: item.aktif
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    if (!form.nomor_rw || !form.nama_rw) return;
    try {
      setSaving(true);
      const headers = { Authorization: `Bearer ${token}` };
      if (editItem) {
        await axios.put(`${API_BASE_URL}/api/rw/profile/${editItem.id}`, form, { headers });
      } else {
        await axios.post(`${API_BASE_URL}/api/rw/profile`, form, { headers });
      }
      setShowForm(false);
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Hapus data RW ini?')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`${API_BASE_URL}/api/rw/profile/${id}`, { headers });
      fetchData();
    } catch (err) {
      alert(err.response?.data?.detail || 'Gagal menghapus');
    }
  };

  if (loading) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full flex items-center justify-center">
        <div className="text-center space-y-4">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto" />
          <p className="text-gray-500 dark:text-gray-400">Memuat profil RW...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
          <p className="text-red-600 dark:text-red-400 text-sm">Error: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>RW</span><span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Profil RW</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl flex items-center justify-center shadow">
            <Building2 className="h-5 w-5 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Profil RW</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Profil dan informasi RW Anda</p>
          </div>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchData} className="flex items-center gap-2 px-3 py-2 text-sm bg-[var(--rw-bg-card)] dark:bg-gray-800 border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
            <RefreshCw className="h-4 w-4" />
          </button>
          {data.length === 0 && (
            <button onClick={openAdd} className="flex items-center gap-2 px-4 py-2 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white text-sm rounded-lg transition-colors">
              <Plus className="h-4 w-4" />Buat Profil RW
            </button>
          )}
        </div>
      </div>

      {/* RW Cards */}
      {data.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {data.map((rw) => (
            <div key={rw.id} className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow overflow-hidden">
              {/* Card Header */}
              <div className="bg-gradient-to-r from-blue-500 to-indigo-600 p-4">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                      <span className="text-white font-bold text-lg">{rw.nomor_rw}</span>
                    </div>
                    <div>
                      <h3 className="text-white font-semibold">{rw.nama_rw}</h3>
                      <p className="text-blue-100 text-xs">RW {rw.nomor_rw}</p>
                    </div>
                  </div>
                  <Badge
                    variant="outline"
                    className={rw.aktif
                      ? 'border-white/50 text-white bg-white/20'
                      : 'border-red-300 text-red-200 bg-red-500/20'
                    }
                  >
                    {rw.aktif ? 'Aktif' : 'Tidak Aktif'}
                  </Badge>
                </div>
              </div>

              {/* Card Body */}
              <div className="p-4 space-y-3">
                {rw.ketua_rw && (
                  <div className="flex items-center gap-2 text-sm">
                    <User className="h-4 w-4 text-gray-400 flex-shrink-0" />
                    <div>
                      <span className="text-gray-500 dark:text-gray-400">Ketua RW: </span>
                      <span className="font-medium text-gray-900 dark:text-white">{rw.ketua_rw}</span>
                    </div>
                  </div>
                )}
                {rw.alamat_sekretariat && (
                  <div className="flex items-start gap-2 text-sm">
                    <MapPin className="h-4 w-4 text-gray-400 flex-shrink-0 mt-0.5" />
                    <div>
                      <span className="text-gray-500 dark:text-gray-400">Sekretariat: </span>
                      <span className="text-gray-700 dark:text-gray-300">{rw.alamat_sekretariat}</span>
                    </div>
                  </div>
                )}
                {!rw.ketua_rw && !rw.alamat_sekretariat && (
                  <p className="text-sm text-gray-400 dark:text-gray-500 italic">Belum ada informasi detail</p>
                )}
              </div>

              {/* Card Actions */}
              <div className="px-4 pb-4 flex gap-2">
                <button
                  onClick={() => openEdit(rw)}
                  className="flex-1 flex items-center justify-center gap-2 px-3 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 transition-colors"
                >
                  <Pencil className="h-3.5 w-3.5" />Edit
                </button>
                <button
                  onClick={() => handleDelete(rw.id)}
                  className="flex items-center justify-center gap-2 px-3 py-2 text-sm border border-red-200 dark:border-red-800 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20 text-red-600 dark:text-red-400 transition-colors"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-12 text-center">
          <Building2 className="h-16 w-16 text-gray-300 dark:text-gray-600 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-300 mb-2">Belum Ada Data RW</h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-6">
            Tambahkan profil RW untuk mulai menggunakan fitur supervisory layer
          </p>
          <button
            onClick={openAdd}
            className="inline-flex items-center gap-2 px-6 py-3 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white rounded-lg transition-colors"
          >
            <Plus className="h-4 w-4" />Tambah RW Pertama
          </button>
        </div>
      )}

      {/* Form Dialog */}
      <Dialog open={showForm} onOpenChange={setShowForm}>
        <DialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-900 max-w-md">
          <DialogHeader>
            <DialogTitle>{editItem ? 'Edit Profil RW' : 'Tambah RW Baru'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Nomor RW <span className="text-red-500">*</span></Label>
                <Input
                  className="mt-1"
                  placeholder="Contoh: 01"
                  value={form.nomor_rw}
                  onChange={e => setForm(f => ({ ...f, nomor_rw: e.target.value }))}
                />
              </div>
              <div>
                <Label>Nama RW <span className="text-red-500">*</span></Label>
                <Input
                  className="mt-1"
                  placeholder="Contoh: RW 01 Botanika"
                  value={form.nama_rw}
                  onChange={e => setForm(f => ({ ...f, nama_rw: e.target.value }))}
                />
              </div>
            </div>
            <div>
              <Label>Ketua RW</Label>
              <Input
                className="mt-1"
                placeholder="Nama ketua RW..."
                value={form.ketua_rw}
                onChange={e => setForm(f => ({ ...f, ketua_rw: e.target.value }))}
              />
            </div>
            <div>
              <Label>Alamat Sekretariat</Label>
              <Input
                className="mt-1"
                placeholder="Alamat sekretariat RW..."
                value={form.alamat_sekretariat}
                onChange={e => setForm(f => ({ ...f, alamat_sekretariat: e.target.value }))}
              />
            </div>
            <div className="flex items-center gap-3">
              <input
                type="checkbox"
                id="aktif-rw"
                checked={form.aktif}
                onChange={e => setForm(f => ({ ...f, aktif: e.target.checked }))}
                className="w-4 h-4 rounded border-gray-300 text-cyan-500"
              />
              <Label htmlFor="aktif-rw" className="cursor-pointer">RW Aktif</Label>
            </div>
          </div>
          <DialogFooter>
            <button
              onClick={() => setShowForm(false)}
              className="px-4 py-2 text-sm border border-[var(--rw-border)] dark:border-gray-700 rounded-lg hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800"
            >
              Batal
            </button>
            <button
              onClick={handleSave}
              disabled={saving || !form.nomor_rw || !form.nama_rw}
              className="px-4 py-2 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white text-sm rounded-lg disabled:opacity-50"
            >
              {saving ? 'Menyimpan...' : 'Simpan'}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default ProfileRW;
