import React from 'react'
import { Twitter, Facebook, Youtube, Instagram, Music2, MessageCircle } from 'lucide-react'
import { Ico } from './Icons.jsx'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'

const SOCIAL_ICONS = [
  { key: 'Twitter',   label: 'Twitter / X', Icon: Twitter },
  { key: 'Facebook',  label: 'Facebook',    Icon: Facebook },
  { key: 'Youtube',   label: 'YouTube',     Icon: Youtube },
  { key: 'Instagram', label: 'Instagram',   Icon: Instagram },
  { key: 'Tiktok',    label: 'TikTok',      Icon: Music2 },
  { key: 'Discord',   label: 'Discord',     Icon: MessageCircle },
]

export default function Footer() {
  const c = useCMS('footer')
  const settings = useAppSettings()
  const { logoUrl, appName } = settings
  // Link media sosial dari Vendor > Settings — sama seperti yang dipakai di
  // halaman login vendor, cuma tampilkan yang diisi & diaktifkan.
  const socialLinks = SOCIAL_ICONS
    .map(({ key, ...rest }) => ({
      ...rest,
      href: settings[`social${key}`],
      enabled: settings[`social${key}Enabled`],
    }))
    .filter((s) => s.href && s.enabled)
  // Section Harga sudah dihilangkan di landing3 — buang link footer yang
  // menuju ke situ juga supaya tidak jadi tautan mati (#harga).
  const cols = (c.columns || []).map((col) => ({
    ...col,
    links: (col.links || []).filter((l) => (l.label || '').toLowerCase() !== 'harga'),
  }))
  return (
    <footer>
      <div className="container">
        <div className="footer-top">
          <div className="footer-col">
            <a href="#" className="brand">
              {logoUrl ? (
                <img src={logoUrl} alt={appName} className="brand-mark-img" />
              ) : (
                <div className="brand-mark">R</div>
              )}
              <div className="brand-name">
                <span>{c.brand_name}</span>
                <small>{c.brand_subtitle}</small>
              </div>
            </a>
            <p className="footer-blurb">{c.blurb}</p>
            <div style={{display:'flex', gap:10}}>
              <a href="#" className="btn btn-ghost" style={{padding:'8px 14px', fontSize:13}}><Ico.Globe /> {c.lang_label}</a>
              <a href="#" className="btn btn-ghost" style={{padding:'8px 14px', fontSize:13}}>{c.status_label}</a>
            </div>
            {socialLinks.length > 0 && (
              <div style={{display:'flex', gap:10, marginTop:16}}>
                {socialLinks.map(({ label, Icon, href }) => (
                  <a
                    key={label}
                    href={href}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={label}
                    style={{
                      width:34, height:34, borderRadius:999, display:'flex',
                      alignItems:'center', justifyContent:'center',
                      border:'1px solid var(--line-2)', color:'var(--ink)',
                    }}
                  >
                    <Icon size={15} />
                  </a>
                ))}
              </div>
            )}
          </div>
          {cols.map((col, i) => (
            <div key={i} className="footer-col">
              <h5>{col.title}</h5>
              <ul>
                {(col.links || []).map((l, j) => (
                  <li key={j}><a href={l.href}>{l.label}</a></li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        <div className="footer-bottom">
          <span>{c.copyright}</span>
          <span>{c.version_label}</span>
        </div>
      </div>
    </footer>
  )
}
