import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { API_BASE_URL } from '../../config/api';
import { ArrowLeft, Image as ImageIcon } from 'lucide-react';

const formatDate = (val) => {
  if (!val) return '-';
  return new Date(val).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' });
};

export default function InformasiKategori() {
  const { kategori } = useParams();
  const { token } = useAuth();
  const navigate = useNavigate();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!token) return;
    setLoading(true);
    axios.get(`${API_BASE_URL}/api/informasi/warga/kategori/${encodeURIComponent(kategori)}`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(res => setData(res.data.data || []))
      .finally(() => setLoading(false));
  }, [token, kategori]);

  return (
    <div className="p-4 md:p-6 max-w-2xl mx-auto space-y-4">
      <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
        <ArrowLeft className="w-4 h-4" /> Kembali
      </button>
      <h1 className="text-xl font-bold text-gray-900 dark:text-white">{decodeURIComponent(kategori)}</h1>

      {loading ? (
        <div className="text-center py-10">
          <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto" />
        </div>
      ) : data.length === 0 ? (
        <div className="text-center py-10 text-gray-400">Belum ada informasi di kategori ini</div>
      ) : (
        <div className="space-y-3">
          {data.map(item => (
            <button
              key={item.id}
              onClick={() => navigate(`/informasi-warga/${item.id}`)}
              className="w-full flex items-center gap-3 bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg p-3 border border-[var(--rw-border)] dark:border-gray-700 hover:shadow-sm transition text-left"
            >
              {item.gambar_header ? (
                <img src={`${API_BASE_URL}/${item.gambar_header}`} alt="" className="w-16 h-16 object-cover rounded-lg flex-shrink-0" />
              ) : (
                <div className="w-16 h-16 rounded-lg bg-gray-200 dark:bg-gray-700 flex items-center justify-center flex-shrink-0">
                  <ImageIcon className="w-5 h-5 text-gray-400" />
                </div>
              )}
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold text-gray-900 dark:text-gray-100 truncate">{item.judul}</p>
                <p className="text-xs text-gray-500 dark:text-gray-400">{formatDate(item.tanggal)}</p>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
