import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from './AuthContext';
import { API_BASE_URL } from '../config/api';

const TenantFeatureContext = createContext(null);

export function TenantFeatureProvider({ children }) {
  const { user, token } = useAuth();
  const [features, setFeatures] = useState(null); // null = not loaded → show all

  useEffect(() => {
    if (!token || !user) {
      setFeatures(null);
      return;
    }
    // Vendor/RW/Kelurahan levels tidak pakai feature gating berbasis paket RT
    if (['pengurus_rw', 'pengurus_kelurahan', 'vendor'].includes(user?.role)) {
      setFeatures(null);
      return;
    }
    fetch(`${API_BASE_URL}/api/tenant/my-features`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.ok ? r.json() : null)
      .then(d => setFeatures(d?.modules || null))
      .catch(() => setFeatures(null)); // fallback: show all
  }, [token, user?.id, user?.role]);

  const hasFeature = useCallback(
    (key) => features === null || features[key] !== false,
    [features]
  );

  return (
    <TenantFeatureContext.Provider value={{ features, hasFeature }}>
      {children}
    </TenantFeatureContext.Provider>
  );
}

export function useTenantFeatures() {
  return useContext(TenantFeatureContext);
}
