import React, { createContext, useContext, useState, useEffect } from "react";
import { useCallback } from "react";

const AuthContext = createContext(null);

export const useAuthHeader = () => {
  const { token } = useAuth();
  return token
    ? { Authorization: `Bearer ${token}` }
    : {};
};
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [expireAt, setExpireAt] = useState(null); // ✅ WAJIB
  const [isLoading, setIsLoading] = useState(true);
  const [showSessionExpired, setShowSessionExpired] = useState(false);

 // --------------------------------------------------
  // LOAD SESSION SAAT REFRESH
  // --------------------------------------------------
  useEffect(() => {
    try {
      const u = localStorage.getItem("user");
      const t = localStorage.getItem("token");
      const e = localStorage.getItem("expireAt");

      if (u && t && e && Date.now() < Number(e)) {
        setUser(JSON.parse(u));
        setToken(t);
        setExpireAt(Number(e));
      } else {
        logout(); // 🔥 AUTO LOGOUT
      }
    } catch (err) {
      console.error("Auth load error:", err);
      logout();
    }


    setIsLoading(false);
  }, []);

  // --------------------------------------------------
  // ⏱ AUTO LOGOUT SAAT SESSION EXPIRED
  // --------------------------------------------------
  useEffect(() => {
    if (!expireAt) return;

    const timeout = setTimeout(() => {
      logout();
      setShowSessionExpired(true);
    }, expireAt - Date.now());

    return () => clearTimeout(timeout);
  }, [expireAt]);

  // --------------------------------------------------
  // SET USER + JWT SETELAH LOGIN
  // --------------------------------------------------
 const setAuthUser = useCallback((userData, jwtToken, expireTime) => {
    setUser(userData);
    setToken(jwtToken);
    setExpireAt(expireTime);
    localStorage.setItem("user", JSON.stringify(userData));
    localStorage.setItem("token", jwtToken);
    localStorage.setItem("expireAt", expireTime);
  }, []);

const logout = useCallback(() => {
    setUser(null);
    setToken(null);
    setExpireAt(null);

    localStorage.removeItem("user");
    localStorage.removeItem("token");
    localStorage.removeItem("expireAt");

     
  }, []);

  return (
    <AuthContext.Provider
      value={{
        user,
        token,   
        expireAt,       // 🔥 JWT READY
        setAuthUser,
        logout,
        isLoading,
        showSessionExpired,
        setShowSessionExpired,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
};
