/**
 * Filter menu items based on database role permissions and active package features.
 * System roles with default-allow: admin, warga, karyawan, staff — show unless explicitly denied.
 * All other roles (pengurus_rt, pengurus_rw, pengurus_kelurahan, staff_kelurahan, and ALL
 * custom roles like Bendahara) use default-deny: only show menus explicitly granted by
 * vendor. staff_kelurahan's RolePermission row is seeded to match pengurus_kelurahan's
 * exactly (same menus/CRUD), except "kel-users" which is forced read-only — see Manajemen
 * Role di Vendor untuk menyesuaikan lebih lanjut kalau diperlukan.
 * Feature gating is a second layer on top — menus without featureKey are never hidden.
 */
const DEFAULT_ALLOW_ROLES = ['admin', 'warga', 'karyawan', 'staff'];

const getMenuItems = (role, dbPermissions, hasFeature, opts, frozenMenuIds) => {
  const allMenus = getAllMenuItems(role, opts);
  const defaultDeny = !DEFAULT_ALLOW_ROLES.includes(role);
  const isFrozen = (id) => frozenMenuIds instanceof Set && frozenMenuIds.has(id);

  const canShow = (permKey) => {
    const perm = dbPermissions[permKey];
    return defaultDeny ? perm?.read === true : perm?.read !== false;
  };

  // Feature check: only hide if features loaded AND feature[key] === false
  const featureOk = (item) => !item.featureKey || hasFeature(item.featureKey);

  return allMenus.filter(menu => {
    if (!featureOk(menu)) return false;
    // Menu yang di-freeze vendor tetap tampil (tidak bisa diklik — lihat
    // render-nya di bawah) terlepas dari permission role, sama seperti
    // alwaysShow tapi khusus untuk menu ini.
    if (menu.alwaysShow || isFrozen(menu.id)) return true;
    if (menu.hasSubmenu && menu.submenu) {
      // Other parent menus: map to their primary permission key
      const permKey =
        menu.id === 'users-menu'      ? 'users-list' :
        menu.id === 'Kepengurusan'    ? 'pengurus'   :
        menu.id === 'residents'       ? 'warga'       :
        menu.id === 'rw-configuration' ? 'rw-kategori-biaya' :
        menu.id;
      return canShow(permKey);
    }
    return canShow(menu.id);
  }).map(menu => {
    if (menu.hasSubmenu && menu.submenu) {
      return {
        ...menu,
        isFrozen: isFrozen(menu.id),
        submenu: menu.submenu
          .filter(sub => sub.alwaysShow || isFrozen(sub.id) || (canShow(sub.id) && featureOk(sub)))
          .map(sub => ({ ...sub, isFrozen: isFrozen(sub.id) }))
      };
    }
    return { ...menu, isFrozen: isFrozen(menu.id) };
  });
};

