import React from 'react'
import { Ico } from './Icons.jsx'
import dashImg from '../../assets/images/landing1.png'
import { useCMS } from './cmsContent.jsx'

const HIDDEN_META = ['tanpa kartu kredit', 'setup < 10 menit']

// Hero landingpage3 — sama seperti landingpage2, kecuali: tombol CTA primer
// ("Mulai 14 hari gratis") dan item meta "Tanpa kartu kredit"/"Setup < 10
// menit" dihilangkan. Penggantian teks "Ruang Warga" -> nama aplikasi vendor
// ditangani terpusat di useCMS (cmsContent.jsx), berlaku untuk semua field
// termasuk subtitle di bawah ini.
export default function Hero() {
  const c = useCMS('hero')
  const ticker = c.ticker || []
  const meta = (c.meta || []).filter((m) => !HIDDEN_META.includes((m || '').toLowerCase()))
  return (
    <section className="hero">
      <div className="hero-decor" aria-hidden="true">
        <div className="coral-sun"></div>
        <div className="mustard-square"></div>
        <div className="dot-grid tl"></div>
        <div className="dot-grid br"></div>
        <div className="line-square" style={{top: 110, right: 360, transform: 'rotate(8deg)'}}></div>
        <div className="line-circle" style={{top: 220, left: 280, width: 180, height: 180}}></div>
      </div>
      <div className="container hero-inner">
        <div>
          <h1 dangerouslySetInnerHTML={{ __html: c.headline_html }} />
          <p className="hero-sub">{c.subtitle}</p>
          <div className="hero-ctas">
            <a href={c.cta_secondary?.href || '#'} className="btn btn-ghost btn-lg">
              {c.cta_secondary?.label}
            </a>
          </div>
          <div className="hero-meta">
            {meta.map((m, i) => (
              <span key={i}><span className="check"><Ico.Check /></span>&nbsp; {m}</span>
            ))}
          </div>
        </div>
        <div className="hero-visual">
          <div className="dash">
            <div className="dash-bar">
              <div className="dot dot-r"></div>
              <div className="dot dot-y"></div>
              <div className="dot dot-g"></div>
              <div className="url">{(c.dashboard_url || '').replace(/ruang-warga/gi, 'merata')}</div>
            </div>
            <img src={dashImg} alt="Dashboard" style={{ width: '100%', display: 'block' }} />
          </div>
        </div>
      </div>
      <div className="ticker" aria-hidden="true">
        <div className="ticker-track">
          {Array.from({length: 2}).map((_, i) => (
            <React.Fragment key={i}>
              {ticker.map((t, j) => (
                <React.Fragment key={j}>
                  <span>{j === 0 && <span className="dot"></span>}{j === 0 ? ' ' : ''}{t}</span>
                  <span>·</span>
                </React.Fragment>
              ))}
            </React.Fragment>
          ))}
        </div>
      </div>
    </section>
  )
}
