import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { API_BASE_URL } from '@/config/api';

// Warna fallback — sama dengan DEFAULT_COLORS di ColorThemeContext.jsx, dipakai
// kalau fetch tema aktif gagal (mis. offline) supaya PDF tetap bisa dibuat.
const FALLBACK_THEME_COLORS = {
  bg_page: '#efe7d2',
  bg_card: '#f7f1de',
  bg_card_alt: '#ece4cf',
  border: '#d5cebc',
  primary: '#ed6f5c',
  primary_hover: '#e05544',
  text_accent: '#ed6f5c',
};

function hexToRgb(hex) {
  const clean = (hex || '').replace('#', '');
  const full = clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean;
  const num = parseInt(full, 16);
  if (Number.isNaN(num) || full.length !== 6) return [0, 0, 0];
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

// Ambil tema warna yang sedang aktif (diatur vendor di menu Settings) supaya
// PDF yang dihasilkan konsisten dengan tampilan aplikasi saat ini — bukan
// warna oranye default yang di-hardcode.
async function getActiveThemeColors() {
  try {
    const res = await fetch(`${API_BASE_URL}/api/app/theme`, { cache: 'no-store' });
    if (!res.ok) return FALLBACK_THEME_COLORS;
    const data = await res.json();
    return data?.colors || FALLBACK_THEME_COLORS;
  } catch {
    return FALLBACK_THEME_COLORS;
  }
}

const isRenderable = (el) => el.offsetParent !== null || el.getClientRects().length > 0;

// Kelompokkan anak-anak berdasarkan offsetTop — anak yang offsetTop-nya sama
// berarti sejajar berdampingan di baris yang sama (kejadian nyata waktu
// breakpoint grid, mis. "md:grid-cols-2 xl:grid-cols-3", aktif di layar
// lebar/iPad). Anak dengan offsetTop beda berarti sudah turun ke baris baru.
function groupByRow(items) {
  const rows = [];
  for (const item of items) {
    const lastRow = rows[rows.length - 1];
    if (lastRow && Math.abs(item.offsetTop - lastRow[0].offsetTop) < 2) {
      lastRow.push(item);
    } else {
      rows.push([item]);
    }
  }
  return rows;
}

// Kumpulkan "blok" atomik dari sebuah kontainer supaya tiap chart/kartu bisa
// di-capture & ditempatkan di PDF secara utuh — tidak pernah terbelah dua
// oleh page break di tengah-tengah (beda dari dulu: satu canvas raksasa
// dipotong tiap N mm, yang bisa memotong tepat di tengah baris legend chart
// — makin sering kejadian di HP karena kontennya jadi jauh lebih tinggi
// waktu grid-nya otomatis turun jadi 1 kolom).
//
// Anak langsung dari root dianggap satu blok. Kalau dia sendiri berisi
// beberapa anak (mis. grid "grid-cols-1 md:grid-cols-2 xl:grid-cols-3" berisi
// beberapa DonutChart), susunannya diukur dari posisi render SAAT INI:
//  - Semua sejajar dalam satu baris (layar lebar, breakpoint grid aktif)
//    → dibiarkan utuh sebagai SATU blok, supaya proporsi berdampingannya
//      persis sama seperti di layar (desktop/laptop/iPad tetap seperti
//      sebelumnya — TIDAK dipecah jadi satu chart per halaman).
//  - Sebagian sejajar lalu sebagian turun baris (mis. iPad 2 kolom: 2 chart
//    sejajar + 1 chart turun) → tiap baris jadi bloknya sendiri; baris yang
//    berisi >1 anak tetap dibungkus bareng supaya sejajarnya tidak hilang.
//  - Semua bertumpuk vertikal (HP, breakpoint grid belum aktif) → tiap anak
//    jadi blok sendiri-sendiri supaya page break tidak pernah jatuh di
//    tengah salah satu chart.
function collectPdfBlocks(root) {
  const children = Array.from(root.children).filter(isRenderable);
  if (!children.length) return [root];

  const blocks = [];
  for (const child of children) {
    const items = Array.from(child.children).filter(isRenderable);
    // Cuma kontainer grid/flex (baris chart yang MEMANG dirancang berjajar,
    // mis. grid demografi) yang layak diperiksa susunannya. Kontainer biasa
    // (mis. kartu StrataEkonomiSection yang isinya header lalu body — bukan
    // grid/flex) selalu dibiarkan utuh satu blok, supaya header tidak
    // kepisah dari isinya.
    const isRowContainer = items.length > 1 && (child.classList.contains('grid') || child.classList.contains('flex'));
    if (!isRowContainer) {
      blocks.push(child);
      continue;
    }

    const rows = groupByRow(items);
    if (rows.length === 1) {
      blocks.push(child);
      continue;
    }

    for (const row of rows) {
      if (row.length === 1) {
        blocks.push(row[0]);
      } else {
        // Baris parsial (bukan satu baris penuh, bukan tumpukan penuh) —
        // bungkus ulang anggota baris ini ke kontainer baru yang mewarisi
        // class grid/flex aslinya, supaya susunan berdampingannya tetap
        // sama persis tapi tidak ikut menyeret baris berikutnya.
        const rowWrapper = child.cloneNode(false);
        row.forEach((el) => rowWrapper.appendChild(el.cloneNode(true)));
        root.appendChild(rowWrapper);
        blocks.push(rowWrapper);
      }
    }
  }
  return blocks;
}

// Elemen yang di layar sengaja discroll horizontal (mis. tabel breakdown
// strata ekonomi per RT/RW yang punya "min-width" dibungkus
// "overflow-x-auto") — kalau di-capture apa adanya, bagian yang butuh
// discroll ikut ke-crop (tidak kelihatan) karena html2canvas cuma
// menangkap area yang benar-benar terlihat (clientWidth-nya), bukan seluruh
// scrollWidth. Di sini scroller yang BENAR-BENAR overflow dilebarkan ke
// lebar kontennya sendiri (max-content) berikut ancestor-nya sampai ke
// akar, supaya capture-nya utuh — sementara bagian lain dari halaman yang
// tidak overflow tidak disentuh sama sekali (lebar & breakpoint aslinya
// dipertahankan persis).
function expandOverflowTables(root) {
  const scrollers = Array.from(root.querySelectorAll('.overflow-x-auto'));
  scrollers.forEach((scroller) => {
    if (scroller.scrollWidth <= scroller.clientWidth + 1) return;
    let node = scroller;
    while (node) {
      node.style.overflow = 'visible';
      node.style.width = 'max-content';
      node.style.maxWidth = 'none';
      if (node === root) break;
      node = node.parentElement;
    }
  });
}

/**
 * Render sebuah elemen DOM (termasuk chart SVG/canvas di dalamnya) menjadi
 * PDF — hasilnya persis sama secara visual dengan yang tampil di layar
 * (chart, warna, angka, tabel, dsb), bukan cuma data mentah dalam bentuk teks.
 *
 * Setiap kartu/chart di dalam elemen di-capture sebagai blok terpisah lalu
 * disusun mengalir ke bawah, pindah halaman kalau tidak muat — supaya tidak
 * ada chart/tabel yang terpotong di tengah oleh batas halaman.
 *
 * Capture-nya dilakukan lewat clone tak-terlihat yang lebarnya DISAMAKAN
 * PERSIS dengan lebar elemen asli saat ini (bukan dipaksa ke lebar
 * "desktop" tertentu) — breakpoint responsif Tailwind (grid 2/3 kolom, dst.)
 * bergantung pada lebar window browser yang sesungguhnya, bukan lebar
 * elemen, jadi memaksa clone ke lebar lain akan membuat breakpoint dan
 * lebar aktual tidak sinkron (chart jadi kepepet/tabrakan). Yang butuh
 * perlakuan khusus cuma elemen yang MEMANG discroll horizontal di layar
 * (lihat expandOverflowTables) — itu saja yang dilebarkan.
 *
 * @param {HTMLElement} element - elemen yang mau di-capture
 * @param {Object} opts
 * @param {string} opts.title - judul di halaman pertama
 * @param {string} [opts.subtitle] - anak judul (mis. "RT 01 / RW 07 / Kelurahan Kebonjati")
 * @param {string} opts.filename - nama file .pdf yang di-download
 * @param {string} [opts.backgroundColor] - warna latar saat capture (default krem sesuai tema app)
 */
export async function exportElementToPdf(element, { title, subtitle, filename, backgroundColor }) {
  if (!element) throw new Error('Elemen untuk di-export tidak ditemukan');

  // Kalau backgroundColor tidak di-override secara eksplisit, pakai warna
  // latar dari tema yang sedang aktif (bukan krem hardcoded), supaya hasil
  // capture konsisten dengan tema yang berlaku saat ini.
  const bg = backgroundColor || (await getActiveThemeColors()).bg_page;

  // Clone off-screen (bukan resize elemen aslinya) supaya tampilan dashboard
  // yang sedang dilihat user tidak ikut berubah selama proses export.
  const originalWidth = element.getBoundingClientRect().width;
  const clone = element.cloneNode(true);
  clone.style.position = 'fixed';
  clone.style.top = '0';
  clone.style.left = '-99999px';
  clone.style.width = `${originalWidth}px`;
  clone.style.zIndex = '-1';
  document.body.appendChild(clone);

  // Beri browser satu frame untuk reflow di lebar aslinya sebelum di-capture.
  await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));

  expandOverflowTables(clone);
  await new Promise((resolve) => requestAnimationFrame(resolve));

  try {
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pageWidth = pdf.internal.pageSize.getWidth();
    const pageHeight = pdf.internal.pageSize.getHeight();
    const margin = 10;
    const contentWidth = pageWidth - margin * 2;

    // Header di halaman pertama saja: judul, subjudul, dan tanggal cetak
    let cursorY = margin;
    pdf.setFontSize(14);
    pdf.setFont(undefined, 'bold');
    pdf.setTextColor(31, 41, 55);
    pdf.text(title, pageWidth / 2, cursorY + 5, { align: 'center' });
    cursorY += 9;

    if (subtitle) {
      pdf.setFontSize(10);
      pdf.setFont(undefined, 'normal');
      pdf.setTextColor(107, 114, 128);
      pdf.text(subtitle, pageWidth / 2, cursorY + 3, { align: 'center' });
      cursorY += 6;
    }

    const tanggalCetak = `Dicetak pada ${new Date().toLocaleString('id-ID', { dateStyle: 'long', timeStyle: 'short' })}`;
    pdf.setFontSize(8);
    pdf.setTextColor(156, 163, 175);
    pdf.text(tanggalCetak, pageWidth / 2, cursorY + 3, { align: 'center' });
    pdf.setTextColor(0, 0, 0);
    cursorY += 8;

    const blocks = collectPdfBlocks(clone);
    const blockGap = 4; // mm jarak antar blok
    let pageHasContent = false;

    for (const block of blocks) {
      const canvas = await html2canvas(block, { scale: 2, backgroundColor: bg, useCORS: true, logging: false });
      const imgHeight = (canvas.height * contentWidth) / canvas.width;
      const imgData = canvas.toDataURL('image/jpeg', 0.92);
      const maxBlockHeight = pageHeight - margin * 2;

      if (imgHeight > maxBlockHeight) {
        // Satu blok sendirian lebih tinggi dari satu halaman penuh (jarang
        // terjadi) — fallback ke potongan per halaman khusus blok ini.
        if (pageHasContent) {
          pdf.addPage();
          cursorY = margin;
        }
        let heightLeft = imgHeight;
        let position = cursorY;
        pdf.addImage(imgData, 'JPEG', margin, position, contentWidth, imgHeight, undefined, 'FAST');
        heightLeft -= (pageHeight - position);
        while (heightLeft > 0) {
          pdf.addPage();
          position = heightLeft - imgHeight;
          pdf.addImage(imgData, 'JPEG', margin, position, contentWidth, imgHeight, undefined, 'FAST');
          heightLeft -= pageHeight;
        }
        cursorY = margin;
        pageHasContent = false;
        continue;
      }

      if (pageHasContent && cursorY + imgHeight > pageHeight - margin) {
        pdf.addPage();
        cursorY = margin;
        pageHasContent = false;
      }

      pdf.addImage(imgData, 'JPEG', margin, cursorY, contentWidth, imgHeight, undefined, 'FAST');
      cursorY += imgHeight + blockGap;
      pageHasContent = true;
    }

    pdf.save(filename);
  } finally {
    document.body.removeChild(clone);
  }
}

/**
 * Laporan Bantuan Sosial — BEDA pendekatan dari exportElementToPdf: di sini
 * kartu ringkasan & tabel penerima dibangun langsung sebagai konten PDF asli
 * (teks + tabel lewat jspdf-autotable), BUKAN hasil screenshot/canvas.
 * Alasannya: konten ini murni tabel/angka (bukan grafik), jadi kalau di-
 * screenshot lalu dipotong per halaman, baris tabel bisa kepotong di tengah
 * dan antar halaman jadi tanpa margin. Dengan autoTable, setiap halaman
 * otomatis dapat margin yang konsisten dan baris tabel tidak pernah terbelah
 * dua halaman (pindah utuh ke halaman berikutnya kalau tidak muat).
 *
 * @param {Object} params
 * @param {Object} params.stats - data dari state bantuanStats (sama seperti yang dipakai BantuanSosialWidget)
 * @param {string} [params.title]
 * @param {string} [params.subtitle] - mis. "RT 01 / RW 07 / Kelurahan Kebonjati"
 * @param {string} params.filename
 */
export async function exportBantuanSosialPdf({ stats, title = 'Laporan Penerima Bantuan Sosial', subtitle, filename }) {
  if (!stats) throw new Error('Data bantuan sosial tidak tersedia');

  const theme = await getActiveThemeColors();
  const primaryRgb = hexToRgb(theme.primary);
  const altRowRgb = hexToRgb(theme.bg_card_alt);

  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 14;
  let cursorY = 16;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.setTextColor(31, 41, 55);
  doc.text(title, pageWidth / 2, cursorY, { align: 'center' });
  cursorY += 6;

  if (subtitle) {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(107, 114, 128);
    doc.text(subtitle, pageWidth / 2, cursorY, { align: 'center' });
    cursorY += 5;
  }

  const tanggalCetak = `Dicetak pada ${new Date().toLocaleString('id-ID', { dateStyle: 'long', timeStyle: 'short' })}`;
  doc.setFontSize(8);
  doc.setTextColor(156, 163, 175);
  doc.text(tanggalCetak, pageWidth / 2, cursorY, { align: 'center' });
  cursorY += 6;

  doc.setTextColor(31, 41, 55);
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  const ringkasan = `${stats.total_penerima || 0} warga penerima bantuan` +
    (stats.total_warga ? ` dari ${stats.total_warga} total warga` : '');
  doc.text(ringkasan, margin, cursorY);
  cursorY += 6;

  // Ringkasan per program bantuan — tabel, bukan kartu-canvas
  const bantuanKeys = stats.bantuan_keys || [];
  if (bantuanKeys.length > 0) {
    autoTable(doc, {
      startY: cursorY,
      head: [['Program Bantuan', 'Jumlah Penerima']],
      body: bantuanKeys.map((key) => [key, String(stats[key] || 0)]),
      styles: { fontSize: 9, cellPadding: 2.5 },
      headStyles: { fillColor: primaryRgb, textColor: 255 },
      margin: { left: margin, right: margin },
      theme: 'grid',
    });
    cursorY = (doc.lastAutoTable?.finalY || cursorY) + 8;
  }

  // Tabel lengkap seluruh penerima (tidak dipotong/paginasi di layar — semua baris masuk PDF)
  const penerima = stats.penerima || [];
  const hasRT = penerima.some((p) => p.rt_name && p.rt_name !== '-');
  const hasRW = penerima.some((p) => p.rw_name && p.rw_name !== '-');

  const head = [[
    'Nama Warga', 'Blok Rumah',
    ...(hasRT ? ['RT'] : []),
    ...(hasRW ? ['RW'] : []),
    'Bantuan Diterima',
  ]];
  const body = penerima.map((p) => [
    p.nama || '-',
    p.blok_rumah || '-',
    ...(hasRT ? [p.rt_name || '-'] : []),
    ...(hasRW ? [p.rw_name || '-'] : []),
    (p.bantuan || []).join(', '),
  ]);

  autoTable(doc, {
    startY: cursorY,
    head,
    body,
    styles: { fontSize: 8.5, cellPadding: 2.5, overflow: 'linebreak' },
    headStyles: { fillColor: [55, 65, 81], textColor: 255 },
    alternateRowStyles: { fillColor: altRowRgb },
    // Margin konsisten di SETIAP halaman (atas/bawah/kiri/kanan) — termasuk
    // saat tabel nyambung ke halaman berikutnya, dan baris tidak pernah
    // terbelah di antara dua halaman.
    margin: { top: margin, left: margin, right: margin, bottom: margin },
    rowPageBreak: 'avoid',
    didDrawPage: (data) => {
      doc.setFontSize(8);
      doc.setTextColor(156, 163, 175);
      doc.text(`Halaman ${data.pageNumber}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
    },
  });

  doc.save(filename);
}
