import axios from 'axios';
import { API_BASE_URL } from '../config/api';
import { getLoginPath } from './tenantSlug';

axios.defaults.baseURL = API_BASE_URL;

// Ngrok requires this header to bypass the browser warning page
const isNgrok = API_BASE_URL.includes('ngrok');
if (isNgrok) {
  axios.defaults.headers.common['ngrok-skip-browser-warning'] = 'true';

  // Patch global fetch so all direct fetch() calls also include the header
  const _originalFetch = window.fetch.bind(window);
  window.fetch = function (url, options = {}) {
    if (typeof url === 'string' && url.includes('ngrok')) {
      options = {
        ...options,
        headers: { 'ngrok-skip-browser-warning': 'true', ...(options.headers || {}) },
      };
    }
    return _originalFetch(url, options);
  };
}

// Inject X-Tenant-ID otomatis dari localStorage
axios.interceptors.request.use((config) => {
  const raw = localStorage.getItem("currentTenant");
  if (raw) {
    try {
      const tenant = JSON.parse(raw);
      if (tenant?.id) config.headers["X-Tenant-ID"] = tenant.id;
    } catch (_) {}
  }
  return config;
});

axios.interceptors.response.use(
  response => response,
  error => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = getLoginPath();
    }
    return Promise.reject(error);
  }
);

export default axios;
