import React, { useRef, useState } from 'react';
import { createPortal } from 'react-dom';

/**
 * Reusable Excel import + template download modal.
 *
 * Props:
 *   show           – boolean
 *   onClose        – () => void
 *   onImported     – () => void
 *   title          – string
 *   templateUrl    – full URL to GET template
 *   importUrl      – full URL to POST .xlsx file
 *   templateName   – filename for download
 *   columns        – string[]
 */
export default function ImportExcelModal({
  show,
  onClose,
  onImported,
  title = 'Import Excel',
  templateUrl,
  importUrl,
  templateName = 'template.xlsx',
  columns = [],
  importModes = [],   // optional: [{ value, label, description }] — kalau kosong, mode selector tidak ditampilkan
}) {
  const fileRef   = useRef(null);
  const [file,    setFile]    = useState(null);
  const [loading, setLoading] = useState(false);
  const [result,  setResult]  = useState(null);
  const [error,   setError]   = useState('');
  const [mode,    setMode]    = useState(importModes[0]?.value || 'insert');

  if (!show) return null;

  const token      = localStorage.getItem('token');
  const authHeader = token ? { Authorization: `Bearer ${token}` } : {};

  const handleDownloadTemplate = async () => {
    try {
      const res = await fetch(templateUrl, { headers: authHeader });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement('a');
      a.href     = url;
      a.download = templateName;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      setError('Gagal mengunduh template: ' + e.message);
    }
  };

  const handleImport = async () => {
    if (!file) { setError('Pilih file .xlsx terlebih dahulu.'); return; }
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const form = new FormData();
      form.append('file', file);
      if (importModes.length > 0) form.append('mode', mode);
      const res  = await fetch(importUrl, {
        method:  'POST',
        headers: authHeader,
        body:    form,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);
      setResult(data);
      if (data.created > 0) onImported?.();
    } catch (e) {
      setError('Import gagal: ' + e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setFile(null);
    setResult(null);
    setError('');
    setMode(importModes[0]?.value || 'insert');
    onClose();
  };

  const modal = (
    <div style={styles.overlay} onClick={(e) => e.target === e.currentTarget && handleClose()}>
      <div style={styles.modal}>
        {/* Header */}
        <div style={styles.header}>
          <span style={{ fontWeight: 700, fontSize: 16 }}>{title}</span>
          <button onClick={handleClose} style={styles.closeBtn}>&times;</button>
        </div>

        <div style={styles.body}>
          {/* Step 1 */}
          <div style={styles.step}>
            <div style={styles.stepNum}>1</div>
            <div style={{ flex: 1 }}>
              <div style={styles.stepTitle}>Unduh Template Excel</div>
              <p style={styles.stepDesc}>
                Isi data di template yang sudah disediakan. Kolom yang wajib diisi ditandai <b>*</b>.
                Hapus baris contoh sebelum mengisi data Anda.
              </p>
              {columns.length > 0 && (
                <div style={styles.colList}>
                  {columns.map((c, i) => (
                    <span key={i} style={styles.colBadge}>{c}</span>
                  ))}
                </div>
              )}
              <button onClick={handleDownloadTemplate} style={styles.btnTemplate}>
                ⬇ Unduh Template
              </button>
            </div>
          </div>

          {/* Step 2 (opsional): Pilih mode import */}
          {importModes.length > 0 && (
            <div style={styles.step}>
              <div style={styles.stepNum}>2</div>
              <div style={{ flex: 1 }}>
                <div style={styles.stepTitle}>Pilih Mode Import</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {importModes.map((m) => (
                    <label key={m.value} style={{
                      ...styles.modeOption,
                      borderColor: mode === m.value ? '#2563eb' : '#e5e7eb',
                      background: mode === m.value ? '#eff6ff' : '#fff',
                    }}>
                      <input
                        type="radio"
                        name="import-mode"
                        checked={mode === m.value}
                        onChange={() => setMode(m.value)}
                        style={{ marginTop: 3 }}
                      />
                      <div>
                        <div style={{ fontWeight: 600, fontSize: 13 }}>{m.label}</div>
                        {m.description && <div style={{ fontSize: 12, color: '#6b7280', marginTop: 2 }}>{m.description}</div>}
                      </div>
                    </label>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Step upload */}
          <div style={{ ...styles.step, borderBottom: 'none', marginBottom: 0 }}>
            <div style={styles.stepNum}>{importModes.length > 0 ? 3 : 2}</div>
            <div style={{ flex: 1 }}>
              <div style={styles.stepTitle}>Upload File Excel</div>
              <p style={styles.stepDesc}>Pilih file .xlsx yang sudah diisi, lalu klik Import.</p>
              <div style={styles.fileRow}>
                <input
                  ref={fileRef}
                  type="file"
                  accept=".xlsx"
                  style={{ display: 'none' }}
                  onChange={e => { setFile(e.target.files[0] || null); setResult(null); setError(''); }}
                />
                <button style={styles.btnChoose} onClick={() => fileRef.current?.click()}>
                  Pilih File
                </button>
                <span style={styles.fileName}>
                  {file ? file.name : 'Belum ada file dipilih'}
                </span>
              </div>

              {error && <div style={styles.errorBox}>{error}</div>}

              {result && (
                <div style={result.created > 0 || result.updated > 0 ? styles.successBox : styles.warnBox}>
                  <b>Hasil Import:</b><br />
                  {result.deleted > 0 && <>Data lama dihapus: <b>{result.deleted}</b><br /></>}
                  Data baru ditambahkan: <b>{result.created}</b>
                  {typeof result.updated === 'number' && <> · Data diperbarui: <b>{result.updated}</b></>}
                  <br />
                  Dilewati / gagal: <b>{result.skipped}</b>
                  {result.errors?.length > 0 && (
                    <ul style={{ margin: '6px 0 0 16px', fontSize: 12 }}>
                      {result.errors.map((e, i) => <li key={i}>{e}</li>)}
                    </ul>
                  )}
                </div>
              )}

              <div style={styles.btnRow}>
                <button onClick={handleClose} style={styles.btnCancel}>Tutup</button>
                <button
                  onClick={handleImport}
                  style={{ ...styles.btnImport, opacity: (!file || loading) ? 0.6 : 1 }}
                  disabled={loading || !file}
                >
                  {loading ? 'Mengimpor...' : 'Import'}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  return createPortal(modal, document.body);
}

const styles = {
  overlay: {
    position: 'fixed',
    top: 0, left: 0, right: 0, bottom: 0,
    background: 'rgba(0,0,0,0.6)',
    backdropFilter: 'blur(4px)',
    WebkitBackdropFilter: 'blur(4px)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 99999,
  },
  modal: {
    background: '#fff',
    borderRadius: 10,
    width: '100%',
    maxWidth: 560,
    boxShadow: '0 8px 32px rgba(0,0,0,0.22)',
    overflow: 'hidden',
    maxHeight: '90vh',
    display: 'flex',
    flexDirection: 'column',
  },
  header: {
    padding: '14px 18px',
    borderBottom: '1px solid #e5e7eb',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    background: '#f8f9fa',
    flexShrink: 0,
  },
  closeBtn: {
    background: 'none', border: 'none', fontSize: 22,
    cursor: 'pointer', color: '#6b7280', lineHeight: 1,
  },
  body: { padding: 20, overflowY: 'auto', flex: 1 },
  step: {
    display: 'flex', gap: 14, marginBottom: 22,
    paddingBottom: 20, borderBottom: '1px solid #f3f4f6',
  },
  stepNum: {
    width: 28, height: 28, borderRadius: '50%',
    background: '#2563eb', color: '#fff',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontWeight: 700, fontSize: 14, flexShrink: 0, marginTop: 2,
  },
  stepTitle: { fontWeight: 600, fontSize: 14, marginBottom: 4 },
  stepDesc:  { fontSize: 13, color: '#6b7280', margin: '0 0 10px' },
  colList:   { display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 10 },
  colBadge:  {
    background: '#eff6ff', border: '1px solid #bfdbfe',
    borderRadius: 4, padding: '2px 7px', fontSize: 11, color: '#1d4ed8',
  },
  modeOption: {
    display: 'flex', gap: 10, alignItems: 'flex-start',
    border: '1px solid #e5e7eb', borderRadius: 8, padding: '10px 12px',
    cursor: 'pointer',
  },
  btnTemplate: {
    padding: '7px 14px', borderRadius: 6, cursor: 'pointer',
    background: '#16a34a', color: '#fff', border: 'none',
    fontSize: 13, fontWeight: 600,
  },
  fileRow:   { display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 },
  btnChoose: {
    padding: '7px 14px', borderRadius: 6, cursor: 'pointer',
    background: '#f3f4f6', border: '1px solid #d1d5db',
    fontSize: 13, whiteSpace: 'nowrap',
  },
  fileName:  { fontSize: 13, color: '#374151', wordBreak: 'break-all' },
  errorBox:  {
    background: '#fef2f2', border: '1px solid #fca5a5', borderRadius: 6,
    padding: '8px 12px', fontSize: 13, color: '#dc2626', marginBottom: 10,
  },
  successBox: {
    background: '#f0fdf4', border: '1px solid #86efac', borderRadius: 6,
    padding: '8px 12px', fontSize: 13, color: '#166534', marginBottom: 10,
  },
  warnBox: {
    background: '#fffbeb', border: '1px solid #fcd34d', borderRadius: 6,
    padding: '8px 12px', fontSize: 13, color: '#92400e', marginBottom: 10,
  },
  btnRow:    { display: 'flex', justifyContent: 'flex-end', gap: 10, marginTop: 8 },
  btnCancel: {
    padding: '7px 18px', borderRadius: 6, cursor: 'pointer',
    background: '#f3f4f6', border: '1px solid #d1d5db', fontSize: 13,
  },
  btnImport: {
    padding: '7px 18px', borderRadius: 6, cursor: 'pointer',
    background: '#2563eb', color: '#fff', border: 'none',
    fontSize: 13, fontWeight: 600,
  },
};
